(function(){const a=document.createElement("link").relList;if(a&&a.supports&&a.supports("modulepreload"))return;for(const t of document.querySelectorAll('link[rel="modulepreload"]'))o(t);new MutationObserver(t=>{for(const n of t)if(n.type==="childList")for(const s of n.addedNodes)s.tagName==="LINK"&&s.rel==="modulepreload"&&o(s)}).observe(document,{childList:!0,subtree:!0});function r(t){const n={};return t.integrity&&(n.integrity=t.integrity),t.referrerPolicy&&(n.referrerPolicy=t.referrerPolicy),t.crossOrigin==="use-credentials"?n.credentials="include":t.crossOrigin==="anonymous"?n.credentials="omit":n.credentials="same-origin",n}function o(t){if(t.ep)return;t.ep=!0;const n=r(t);fetch(t.href,n)}})();const h={T:{"tension discs":"discos de tensión","leaves the tip at":"sale de la punta con","tension in the thread":"tensión en el hilo","Tension along the thread path":"Tensión a lo largo del recorrido del hilo","The tension grows at each bend: the discs give {b} N, the bends multiply it by {k} in all.":"La tensión crece en cada curva: los discos dan {b} N y las curvas la multiplican por {k} en total.","last nail":"último clavo",guide:"guía","Δ only grows during a turn (0 to 180°), so L only grows:":"Δ solo crece durante un giro (de 0 a 180°), así que L solo crece:","the thread is always being pulled, never pushed back.":"siempre se tira del hilo, nunca se lo empuja de vuelta.","Payout geometry":"Geometría de la salida del hilo","Seen from the board, the guide runs round the rim; the line from the last nail to the guide is what pulls thread off the cone.":"Visto desde el tablero, la guía recorre el borde; la línea del último clavo a la guía es la que tira del hilo del cono.","board speed ω":"velocidad del tablero ω","thread payout speed dL/dt":"velocidad de salida del hilo dL/dt","thread payout acceleration d²L/dt²":"aceleración de salida del hilo d²L/dt²","time, s":"tiempo, s","Acceleration diagram":"Diagrama de aceleración","One 120° turn of the board, from the last nail, with the machine's own speed and acceleration. The thread's speed peaks at {v} m/s and its acceleration at {a} m/s², both inside the bounds R·ω and R·α the working uses. When the board brakes, the thread slows down ({d} m/s²): a spool turning on a pin would overrun and throw slack, a standing cone cannot.":"Un giro de 120° del tablero desde el último clavo, con la velocidad y la aceleración de la propia máquina. La velocidad del hilo llega a {v} m/s y su aceleración a {a} m/s², ambas dentro de los límites R·ω y R·α que usan los cálculos. Cuando el tablero frena, el hilo se desacelera ({d} m/s²): un carrete que gira sobre un eje seguiría girando y soltaría hilo flojo; un cono fijo no puede.","Spool turning on a pin, felt brake":"Carrete que gira sobre un eje, freno de fieltro","brake M":"freno M","Standing cone, tension discs":"Cono fijo, discos de tensión",eyelet:"ojal",balloon:"balón",spring:"resorte","disc friction":"fricción de los discos","The spool's forces":"Las fuerzas en el carrete","On a pin, the brake's torque divides by a radius that shrinks as the spool empties, and the spool's inertia adds {i} N. On a standing cone nothing turns: the tension comes from the discs alone.":"Sobre un eje, el par del freno se divide por un radio que se achica a medida que el carrete se vacía, y la inercia del carrete suma {i} N. En un cono fijo nada gira: la tensión viene solo de los discos.","Sag of the longest line":"Comba de la línea más larga","A line sags until the tension's slight downward tilt at each end carries its weight. The sag is drawn hundreds of times larger: at {t} N it is {s} mm.":"Una línea se comba hasta que la leve inclinación hacia abajo de la tensión en cada extremo sostiene su peso. La comba está dibujada cientos de veces más grande: a {t} N es de {s} mm.","Seen from above":"Visto desde arriba",resultant:"resultante","Seen from the side":"Visto de lado",board:"tablero","Forces on the busiest nail":"Fuerzas en el clavo más usado","Each wrap's two legs pull into the board; their sideways parts mostly cancel and the inward parts add up to F. F acts {h} mm above where the nail is held, bending it: the steel must not yield.":"Los dos tramos de cada vuelta tiran hacia el interior del tablero; sus partes laterales casi se anulan y las partes hacia adentro suman F. F actúa {h} mm por encima de donde se sujeta el clavo y lo dobla: el acero no debe ceder.",window:"margen","no window":"sin margen","straight lines":"líneas rectas","nail bends":"el clavo se dobla",set:"ajustado","peak, cone":"pico, cono","peak, spool on pin":"pico, carrete sobre eje","The tension window":"El margen de tensión","The tension must sit between what keeps lines straight and what bends the busiest nail. The peaks show why the thread stands on a cone.":"La tensión debe quedar entre lo que mantiene rectas las líneas y lo que dobla el clavo más usado. Los picos muestran por qué el hilo va en un cono fijo.","needed, standing cone":"necesaria, cono fijo","needed, spool on a pin":"necesaria, carrete sobre eje","app minimum":"mínimo de la aplicación","your thread":"tu hilo","thread diameter, mm":"diámetro del hilo, mm","breaking strength, N":"resistencia a la rotura, N","Thread strength against diameter":"Resistencia del hilo según el diámetro","Strength grows with the square of the diameter. Where a fibre's curve crosses a dashed line is the thinnest thread of that fibre that is safe.":"La resistencia crece con el cuadrado del diámetro. Donde la curva de una fibra cruza una línea punteada está el hilo más delgado y seguro de esa fibra.","Straight lines need at least {m} N.":"Las líneas rectas necesitan al menos {m} N.","The busiest nail ({n} wraps, {d} mm) bends above about {l} N.":"El clavo más usado ({n} vueltas, {d} mm) se dobla por encima de unos {l} N.","The thread breaks at about {b} N and should hold {r} N.":"El hilo se rompe a unos {b} N y debería aguantar {r} N.","The app's thinnest thread is {d} mm.":"El hilo más delgado de la aplicación es de {d} mm.","These numbers work: {t} N is inside the window.":"Estos números funcionan: {t} N está dentro del margen.","Something needs changing:":"Hay algo que cambiar:","The machine winds at {t} N: enough for straight lines (at least {a} N), below what bends the busiest nail (about {b} N with 1.5 mm nails and {n} wraps). It stands the thread on a cone with tension discs, and the thread must be at least {d} mm. Every step, with your own numbers, is on the calculations page.":"La máquina enrolla a {t} N: suficiente para líneas rectas (al menos {a} N) y por debajo de lo que dobla el clavo más usado (unos {b} N con clavos de 1,5 mm y {n} vueltas). Pone el hilo en un cono fijo con discos de tensión, y el hilo debe tener al menos {d} mm. Cada paso, con tus propios números, está en la página de cálculos.","Hex bolt M8 × 60":"Perno hexagonal M8 × 60","the pin the thread cone stands on":"el eje sobre el que se apoya el cono de hilo","Eyelet and tension bracket":"Soporte del ojal y la tensión","Above the cone: the eyelet for the thread and the M4 post for the tension discs (tap it M4).":"Sobre el cono: el ojal para el hilo y el eje M4 de los discos de tensión (hazle rosca M4).","Tension discs":"Discos de tensión","Cone pin, M8 bolt":"Eje del cono, perno M8","Winding tension":"Tensión de enrollado","How hard the thread is pulled as it leaves the guide, set at the disc tensioner. About 0.25 N: the thread should just lift 25 g. The build page shows the working.":"Con qué fuerza se tira del hilo al salir de la guía; se ajusta en los discos de tensión. Unos 0,25 N: el hilo apenas debe levantar 25 g. La página de construcción muestra los cálculos.","Winding at {t} N: the longest line needs at least {m} N to lie straight, and the busiest nail ({n} wraps) bends above about {l} N. The thread breaks at about {b} N; the highest tension while winding is about {p} N.":"Enrollando a {t} N: la línea más larga necesita al menos {m} N para quedar recta, y el clavo más usado ({n} vueltas) se dobla por encima de unos {l} N. El hilo se rompe a unos {b} N; la tensión más alta al enrollar es de unos {p} N.","Lower the tension, or use 2 mm nails.":"Baja la tensión o usa clavos de 2 mm.","Raise the tension a little.":"Sube un poco la tensión.","The thread is too thin to be safe: it should hold at least {r} N. Use 0.15 mm polyester or thicker.":"El hilo es demasiado delgado para ser seguro: debería aguantar al menos {r} N. Usa poliéster de 0,15 mm o más grueso.","dancer eye":"ojo del brazo tensor","PTFE tube, all its bends":"tubo de PTFE, todas sus curvas","guide tube tip":"punta del tubo guía",polyester:"poliéster",nylon:"nailon",cotton:"algodón","How hard the machine pulls the thread decides two things: whether the busiest nails bend, and how thin the thread may be. Each step below gives its formula with the numbers put in. Friction coefficients, the nails' steel and the threads' strength are typical values, not measurements, so check the real tension once the machine runs.":"La fuerza con que la máquina tira del hilo decide dos cosas: si los clavos más usados se doblan y qué tan delgado puede ser el hilo. Cada paso de abajo da su fórmula con los números puestos. Los coeficientes de fricción, el acero de los clavos y la resistencia de los hilos son valores típicos, no mediciones, así que comprueba la tensión real cuando la máquina funcione.","1. Where the tension comes from":"1. De dónde viene la tensión","The thread runs from the cone through the tension discs, the dancer eye, the PTFE tube and the guide tube, then over the tube's tip to the nail. The tension as it leaves the tip is the tension the line keeps on the board:":"El hilo va del cono por los discos de tensión, el ojo del brazo tensor, el tubo de PTFE y el tubo guía, y luego por la punta del tubo hasta el clavo. La tensión con que sale de la punta es la que la línea conserva en el tablero:","2. How fast thread is pulled off":"2. Qué tan rápido se tira del hilo","While the board turns, the line from the last nail to the guide grows at most as fast as the rim moves. It never shortens: each wrap ends on the side facing the next nail, so the line only lengthens, and the thread never goes slack.":"Mientras gira el tablero, la línea del último clavo a la guía crece como mucho tan rápido como se mueve el borde. Nunca se acorta: cada vuelta termina del lado que mira al clavo siguiente, así que la línea solo se alarga y el hilo nunca queda flojo.","3. Friction along the path":"3. Fricción a lo largo del recorrido","Where the thread bends round something it rubs, and the tension grows by e<sup>μθ</sup> (the capstan equation; θ is the bend in radians, μ the friction coefficient):":"Donde el hilo se dobla alrededor de algo, roza, y la tensión crece en e<sup>μθ</sup> (la ecuación del cabrestante; θ es el ángulo de la curva en radianes, μ el coeficiente de fricción):",Point:"Punto","So the tension discs only have to give about a third of the tension wanted on the board.":"Así que los discos de tensión solo tienen que dar más o menos un tercio de la tensión que se quiere en el tablero.","4. The spool's inertia":"4. La inercia del carrete","A spool that turns on a pin has to be speeded up with the thread. A full one (thread and core {m} g, radius {ro} mm on a {ri} mm core):":"Un carrete que gira sobre un eje tiene que acelerarse junto con el hilo. Uno lleno (hilo y núcleo {m} g, radio {ro} mm sobre un núcleo de {ri} mm):","A cone that stands still only speeds up the thread itself: {t} N, nothing.":"Un cono que no gira solo acelera el propio hilo: {t} N, nada.","5. As the spool empties":"5. A medida que se vacía el carrete","A felt brake on a turning spool gives a fixed torque <i>M</i>, so the tension is <i>T</i> = <i>M</i> / <i>r</i>: from a full spool to the core it grows {x} times. Pulled off the top of a standing cone through tension discs, it hardly changes (about ±{v} %). Either way, the friction is a little stronger at each start than while sliding (about ×{s}).":"Un freno de fieltro sobre un carrete que gira da un par fijo <i>M</i>, así que la tensión es <i>T</i> = <i>M</i> / <i>r</i>: del carrete lleno al núcleo crece {x} veces. Sacado por arriba de un cono fijo a través de discos de tensión, apenas cambia (unos ±{v} %). En ambos casos, la fricción es un poco mayor en cada arranque que al deslizar (unas ×{s}).","6. Lower limit: straight lines":"6. Límite inferior: líneas rectas","The board lies flat while it is wound, so a line sags under its own weight. The thread ({d} mm, about {x} tex, that is {x} g per km) weighs":"El tablero está horizontal mientras se enrolla, así que una línea cuelga por su propio peso. El hilo ({d} mm, unos {x} tex, es decir {x} g por km) pesa","At {t} N the longest line ({l} m) sags {s} mm.":"A {t} N la línea más larga ({l} m) cuelga {s} mm.","7. Upper limit: the busiest nail":"7. Límite superior: el clavo más usado","Each wrap pulls the nail with two legs of tension <i>T</i>, both heading into the board. A line to a nail Δ away leaves at (90° − Δ/2) from straight inward; averaged over the lines allowed, the inward share is <i>s</i>, and the sideways shares mostly cancel. The wraps sit {z0} to {z1} mm up, so the pull acts about <i>h</i> above where the nail is held (adding one nail diameter for the wood giving way).":"Cada vuelta tira del clavo con dos tramos de tensión <i>T</i>, ambos hacia el interior del tablero. Una línea hacia un clavo a Δ de distancia sale a (90° − Δ/2) de la dirección hacia adentro; en promedio sobre las líneas permitidas, la parte hacia adentro es <i>s</i>, y las partes laterales casi se anulan. Las vueltas están de {z0} a {z1} mm de altura, así que el tirón actúa unos <i>h</i> por encima de donde se sujeta el clavo (sumando un diámetro de clavo porque la madera cede).",Nail:"Clavo","Steel {s} MPa":"Acero {s} MPa","The wood holds well below that, and the nail bends elastically only a few hundredths of a millimetre: the risk is the steel yielding, which leaves the nail leaning in for good.":"La madera aguanta mucho más, y el clavo se dobla elásticamente solo unas centésimas de milímetro: el riesgo es que el acero ceda y el clavo quede inclinado hacia adentro para siempre.","8. The highest tension the thread sees":"8. La tensión más alta que soporta el hilo","spool on a pin":"carrete sobre un eje","standing cone":"cono fijo","With a spool on a pin the steady tension near its core would be {t} N, above what the nails take: that is why the machine stands the thread on a cone.":"Con un carrete sobre un eje, la tensión estable cerca del núcleo sería de {t} N, más de lo que aguantan los clavos: por eso la máquina pone el hilo sobre un cono fijo.","9. How thin the thread may be":"9. Qué tan delgado puede ser el hilo","The thread must hold the highest tension {sf} times over, also at the knot that ties it on (a knot keeps about {k} % of the strength). Its strength per tex and its density give the diameter (fibres fill about {f} % of a twisted thread):":"El hilo debe aguantar {sf} veces la tensión más alta, también en el nudo con que se ata (un nudo conserva cerca del {k} % de la resistencia). Su resistencia por tex y su densidad dan el diámetro (las fibras llenan cerca del {f} % de un hilo torcido):","strength per tex":"resistencia por tex",Strength:"Resistencia","Standing cone":"Cono fijo","Spool on a pin":"Carrete sobre un eje","10. What it means":"10. Qué significa","<b>Wind at {a}–{b} N; {t} N is set.</b> The thread leaving the guide should just lift a {g} g weight (or read it on a luggage scale).":"<b>Enrolla a {a}–{b} N; está puesto en {t} N.</b> El hilo que sale de la guía debe apenas levantar un peso de {g} g (o léelo en una balanza de equipaje).","<b>The thread stands on a cone</b> and comes off over its top through tension discs, so the tension stays put as the cone empties.":"<b>El hilo está en un cono fijo</b> y sale por arriba a través de discos de tensión, así que la tensión no cambia a medida que el cono se vacía.","<b>Thread at least {d} mm</b>: thinner would hold in theory, but leaves nothing for wear at the tube tip or a weak spot. The app does not go below it. The usual {u} mm polyester holds the peak {s} times over.":"<b>Hilo de al menos {d} mm</b>: uno más delgado aguantaría en teoría, pero no deja margen para el desgaste en la punta del tubo ni para un punto débil. La aplicación no baja de ahí. El poliéster habitual de {u} mm aguanta {s} veces el pico.","<b>2 mm nails</b> for pieces whose busiest nail gets more than about 25 wraps (the machine page counts them and warns).":"<b>Clavos de 2 mm</b> para piezas cuyo clavo más usado recibe más de unas 25 vueltas (la página de la máquina las cuenta y avisa).","<b>The turntable motor</b> feels the thread as {a} N·m extra, {b} N·m at the peak: nothing next to what it has.":"<b>El motor de la plataforma</b> nota el hilo como {a} N·m extra, {b} N·m en el pico: nada comparado con lo que tiene.","<b>Tie the thread to nail {n}</b>, check it runs freely from the spool through the guide, then press Resume.":"<b>Ata el hilo al clavo {n}</b>, comprueba que corre libre desde el carrete por la guía y pulsa Reanudar.","<b>Planned stop after {n} lines.</b> Check the thread and the tension, then press Resume.":"<b>Parada prevista tras {n} líneas.</b> Revisa el hilo y la tensión y pulsa Reanudar.","<b>Finished!</b> Tie the thread off at nail {n}, then press Resume to lift the guide clear.":"<b>¡Terminado!</b> Ata el final del hilo en el clavo {n} y pulsa Reanudar para retirar la guía.","<b>Paused</b> at about line {n}. Resume, stop, or go back a few lines.":"<b>En pausa</b> hacia la línea {n}. Reanuda, detén o retrocede unas líneas.","<b>The machine stopped on its own</b> at about line {n}: the thread may have broken or run out. Mend it and press Resume, or go back a few lines and wind them again.":"<b>La máquina se detuvo sola</b> hacia la línea {n}: puede que el hilo se haya roto o acabado. Arréglalo y pulsa Reanudar, o retrocede unas líneas y vuelve a enrollarlas.",Connected:"Conectada","Connect the machine":"Conectar la máquina",ready:"lista",running:"en marcha",holding:"en espera",jogging:"moviendo a mano",alarm:"alarma",homing:"buscando el inicio","door open":"puerta abierta","check mode":"modo de comprobación",asleep:"en reposo","waiting for the controller…":"esperando al controlador…","feed {f} %":"avance {f} %","Line {k} of {l} · {a} of {t} commands sent":"Línea {k} de {l} · {a} de {t} comandos enviados","The controller refused line {l} (error {c}: <code>{t}</code>). The winding is held: resume to skip it, or stop.":"El controlador rechazó la línea {l} (error {c}: <code>{t}</code>). El enrollado está en espera: reanuda para saltarla, o detenlo.","Alarm {c}: the controller has stopped and needs unlocking ($X) or homing. If the board turned while stopped, set the zero again.":"Alarma {c}: el controlador se detuvo y hay que desbloquearlo ($X) o llevarlo al inicio. Si el tablero giró mientras estaba detenido, vuelve a fijar el cero.","The winding is finished: {n} lines.":"El enrollado está terminado: {n} líneas.","Stopped; the position is kept. To carry on, unwind the thread back to nail {n} and start from line {k}.":"Detenida; la posición se conserva. Para seguir, desenrolla el hilo hasta el clavo {n} y empieza desde la línea {k}.","The connection to the controller was lost.":"Se perdió la conexión con el controlador.","Connected. GRBL answers with a welcome line; press Unlock or Home if it reports an alarm.":"Conectada. GRBL responde con una línea de bienvenida; pulsa Desbloquear o Ir al inicio si informa una alarma.","Starting at line {k}: the guide rises, goes inside the ring and turns to nail {n}, then stops for the thread.":"Empezando en la línea {k}: la guía sube, entra en el aro y gira hasta el clavo {n}; luego se detiene para el hilo.","Winding from line {k}.":"Enrollando desde la línea {k}.","Sending the settings, one at a time.":"Enviando los ajustes, uno por uno.","Zero set: X0 at nail 0, Y0 on the nail circle, Z at the nail tops.":"Cero fijado: X0 en el clavo 0, Y0 sobre el círculo de clavos, Z a la altura de las cabezas de los clavos.","status shows the work position and buffer use":"el estado muestra la posición de trabajo y el uso del búfer","step pulse, µs":"pulso de paso, µs","keep the motors powered when idle, so the board cannot drift":"mantener los motores alimentados en reposo, para que el tablero no se desplace","limit switches: normally open":"interruptores de límite: normalmente abiertos","no soft limits: the board turns many times":"sin límites por software: el tablero da muchas vueltas","no hard limits":"sin límites físicos","homing on":"búsqueda de inicio activada","home X towards −, Y towards +, Z towards +":"inicio de X hacia −, Y hacia +, Z hacia +","homing feed, °/min or mm/min":"avance de búsqueda fina, °/min o mm/min","homing seek, °/min or mm/min":"velocidad de búsqueda, °/min o mm/min","pull-off after homing, mm":"retroceso tras el inicio, mm","X steps per degree of board turn":"pasos de X por grado de giro del tablero","Y steps per mm":"pasos de Y por mm","Z steps per mm":"pasos de Z por mm","X top speed, °/min":"velocidad máxima de X, °/min","Y top speed, mm/min":"velocidad máxima de Y, mm/min","Z top speed, mm/min":"velocidad máxima de Z, mm/min","X acceleration, °/s²":"aceleración de X, °/s²","Y acceleration, mm/s²":"aceleración de Y, mm/s²","Z acceleration, mm/s²":"aceleración de Z, mm/s²","Wood and board":"Madera y tablero",Mechanics:"Mecánica",Electronics:"Electrónica","Thread and consumables":"Hilo y consumibles","Birch plywood 18 mm, for the base":"Contrachapado de abedul de 18 mm, para la base","760 × 940 mm":"760 × 940 mm","Birch plywood 12 mm, for the platter":"Contrachapado de abedul de 12 mm, para el plato","a 700 mm disc":"un disco de 700 mm","Birch plywood 18 mm, for the nail board":"Contrachapado de abedul de 18 mm, para el tablero de clavos","a 640 mm disc, one per piece":"un disco de 640 mm, uno por pieza","Panel pins (brads)":"Clavos de panel (puntas)","1.5 × 30 mm, a pack of 500":"1,5 × 30 mm, paquete de 500","Furniture feet":"Patas para muebles","75 mm tall, screw-on":"75 mm de alto, atornillables","Lazy-susan bearing":"Rodamiento giratorio (lazy susan)","305 mm (12 in), aluminium, 100 kg or more":"305 mm (12 in), aluminio, 100 kg o más","Steel dowel":"Pasador de acero","Ø 10 × 40 mm":"Ø 10 × 40 mm","Aluminium extrusion 2040 (V-slot)":"Perfil de aluminio 2040 (V-slot)","260 mm, with T-nuts":"260 mm, con tuercas en T","Screws, nuts and washers":"Tornillos, tuercas y arandelas","M3, M4 and M5 assortment; 4 × 16 mm wood screws":"surtido M3, M4 y M5; tornillos para madera de 4 × 16 mm","Stepper motor NEMA 17":"Motor paso a paso NEMA 17","42 × 48 mm, 0.45 N·m, 1.5 A":"42 × 48 mm, 0,45 N·m, 1,5 A","Stepper motor NEMA 17 with T8 lead screw":"Motor paso a paso NEMA 17 con husillo T8","200 mm screw, 8 mm lead, anti-backlash nut":"husillo de 200 mm, avance de 8 mm, tuerca antiholgura","GT2 pulley, 20 teeth":"Polea GT2, 20 dientes","5 mm bore, for 6 mm belt":"eje de 5 mm, para correa de 6 mm","GT2 idler, 20 teeth":"Polea tensora GT2, 20 dientes","5 mm bore":"eje de 5 mm","GT2 closed belt":"Correa GT2 cerrada","400 mm, 6 mm wide":"400 mm, 6 mm de ancho","GT2 open belt":"Correa GT2 abierta","6 mm wide, 0.5 m":"6 mm de ancho, 0,5 m","Linear rail MGN12H":"Guía lineal MGN12H","200 mm, one carriage":"200 mm, un carro","Linear rail MGN9H":"Guía lineal MGN9H","120 mm, one carriage":"120 mm, un carro","Arduino Uno (or compatible)":"Arduino Uno (o compatible)","with GRBL 1.1 flashed":"con GRBL 1.1 cargado","CNC Shield V3":"CNC Shield V3","for the Uno":"para el Uno","Stepper driver TMC2209":"Driver de motor paso a paso TMC2209","standalone (step/dir) module":"módulo autónomo (step/dir)","Power supply 12 V 5 A":"Fuente de alimentación 12 V 5 A","with a switch or switched cable":"con interruptor o cable con interruptor","Microswitch with lever":"Microinterruptor con palanca","Y and Z home, thread break":"inicio de Y y Z, rotura del hilo","Hall sensor A3144 and a magnet":"Sensor Hall A3144 y un imán","magnet Ø 6 × 3 mm, for homing the turntable":"imán de Ø 6 × 3 mm, para el punto de inicio de la plataforma","Wire, connectors and a project box":"Cables, conectores y una caja","4-wire motor cables, Dupont leads":"cables de motor de 4 hilos, cables Dupont","Brass tube":"Tubo de latón","2.5 mm outside, 1.6 mm inside, cut to 40 mm":"2,5 mm exterior, 1,6 mm interior, cortado a 40 mm","PTFE tube":"Tubo de PTFE","4 × 2 mm, 0.5 m":"4 × 2 mm, 0,5 m","Thread tension discs":"Discos de tensión del hilo","two Ø 16 mm discs, a spring and a wing nut on an M4 bolt, as on a sewing machine":"dos discos de Ø 16 mm, un resorte y una tuerca de mariposa en un perno M4, como en una máquina de coser","Black polyester thread on a cone":"Hilo negro de poliéster en cono","0.15 to 0.3 mm (0.25 mm usual), 3,000 m or more per piece":"de 0,15 a 0,3 mm (lo habitual 0,25 mm), 3.000 m o más por pieza","Filament PETG":"Filamento PETG","about 0.5 kg for all printed parts":"unos 0,5 kg para todas las piezas impresas","Turntable pulley, 160 teeth":"Polea de la plataforma, 160 dientes","PETG, 0.1 mm layers for the teeth, 4 walls, 40 % infill. Hub down.":"PETG, capas de 0,1 mm para los dientes, 4 paredes, 40 % de relleno. Con el cubo abajo.","Turntable motor plate":"Placa del motor de la plataforma","Under the base; the slots tension the belt.":"Bajo la base; las ranuras tensan la correa.","Turn button":"Traba giratoria","Three hold the nail board on the platter.":"Tres sujetan el tablero de clavos sobre el plato.","Hall sensor holder":"Soporte del sensor Hall","On the base, under the magnet's path.":"En la base, bajo el recorrido del imán.","Tower foot, left":"Pie de la torre, izquierdo","Holds the extrusion upright.":"Mantiene el perfil vertical.","Tower foot, right":"Pie de la torre, derecho","Height motor mount":"Soporte del motor de altura","On top of the extrusion.":"Encima del perfil.","Height carriage with shelf":"Carro de altura con repisa","PETG, 5 walls, 40 % infill. Shelf down; the gussets need no support.":"PETG, 5 paredes, 40 % de relleno. Con la repisa abajo; los refuerzos no necesitan soporte.","Guide arm":"Brazo guía","Press the brass tube in from below; the PTFE tube pushes into the socket on top.":"Inserta a presión el tubo de latón desde abajo; el tubo de PTFE entra en el alojamiento de arriba.","Cone stand":"Soporte del cono","The thread cone stands on it, on an M8 bolt; the thread comes off over the top.":"El cono de hilo se apoya en él, sobre un perno M8; el hilo sale por arriba.","Dancer bracket":"Soporte del brazo tensor","Carries the dancer's pivot and the thread-break switch.":"Lleva el pivote del brazo tensor y el interruptor de rotura del hilo.","Dancer arm":"Brazo tensor","Rides on the thread; if the thread breaks it drops onto the switch.":"Se apoya en el hilo; si el hilo se rompe, cae sobre el interruptor.","Base, 18 mm plywood":"Base, contrachapado de 18 mm","Platter, 12 mm plywood":"Plato, contrachapado de 12 mm","Nail board":"Tablero de clavos","Centre dowel":"Pasador central","Homing magnet":"Imán de referencia","Tower, 2040 extrusion":"Torre, perfil 2040","Height rail, MGN12":"Guía de altura, MGN12","Height rail carriage":"Carro de la guía de altura","Guide rail, MGN9":"Guía de la guía de hilo, MGN9","Guide rail carriage":"Carro de la guía MGN9","Height motor with lead screw":"Motor de altura con husillo","Guide motor":"Motor de la guía","Turntable motor":"Motor de la plataforma","Guide belt pulley":"Polea de la correa de la guía","Guide belt idler":"Polea tensora de la guía","Guide belt":"Correa de la guía","Motor pulley, 20 teeth":"Polea del motor, 20 dientes","Turntable belt":"Correa de la plataforma","Brass guide tube":"Tubo guía de latón","PTFE tube for the thread":"Tubo de PTFE para el hilo","Thread cone":"Cono de hilo","Thread-break switch":"Interruptor de rotura del hilo","Controller: Arduino Uno with CNC Shield":"Controlador: Arduino Uno con CNC Shield","Power supply":"Fuente de alimentación",Foot:"Pata","<b>Print</b> the parts below. PETG is best for the pulley and the carriage, which carry load; PLA will do for the rest.":"<b>Imprime</b> las piezas de abajo. El PETG es mejor para la polea y el carro, que soportan carga; para el resto sirve PLA.","<b>Base.</b> Cut the board to size and cut the opening for the pulleys and the belt. Drill the holes from the drilling plan and screw on the feet.":"<b>Base.</b> Corta el tablero a medida y la abertura para las poleas y la correa. Taladra los agujeros del plano y atornilla las patas.","<b>Bearing.</b> Centre the bearing on the opening and screw its lower plate to the base. Drill the 20 mm access hole where one of the upper plate's holes falls.":"<b>Rodamiento.</b> Centra el rodamiento sobre la abertura y atornilla su placa inferior a la base. Taladra el agujero de acceso de 20 mm donde cae uno de los agujeros de la placa superior.","<b>Platter.</b> Cut the 700 mm disc and drill the 10 mm centre hole and the magnet hole underneath. Screw the turntable pulley to its underside, with the dowel through both, then glue the magnet in.":"<b>Plato.</b> Corta el disco de 700 mm y taladra el agujero central de 10 mm y el del imán por debajo. Atornilla la polea de la plataforma a su cara inferior, con el pasador atravesando ambos, y luego pega el imán.","<b>Turntable.</b> Set the platter on the bearing and screw it on through the access hole, turning it to reach each screw.":"<b>Plataforma.</b> Coloca el plato sobre el rodamiento y atorníllalo a través del agujero de acceso, girándolo para alcanzar cada tornillo.","<b>Turntable drive.</b> Fix the motor to its plate, put the 20-tooth pulley on so its teeth line up with the big pulley, fit the belt and slide the plate outward until the belt is firm but not tight; then screw the plate down.":"<b>Transmisión de la plataforma.</b> Fija el motor a su placa, coloca la polea de 20 dientes alineada con la polea grande, pon la correa y desliza la placa hacia afuera hasta que la correa quede firme pero no tirante; luego atornilla la placa.","<b>Homing sensor.</b> Screw the hall sensor holder under the magnet's path, the sensor's flat face up, 1 to 2 mm below the magnet.":"<b>Sensor de referencia.</b> Atornilla el soporte del sensor Hall bajo el recorrido del imán, con la cara plana del sensor hacia arriba, de 1 a 2 mm por debajo del imán.","<b>Tower.</b> Bolt the extrusion upright with the two feet, fit the MGN12 rail on its front face and the height motor on top.":"<b>Torre.</b> Atornilla el perfil vertical con los dos pies, monta la guía MGN12 en su cara frontal y el motor de altura arriba.","<b>Carriage.</b> Bolt the height carriage to the rail carriage and the lead-screw nut to its tab. Fit the MGN9 rail under the shelf, the guide motor and its pulley on the shelf, and the idler at the front.":"<b>Carro.</b> Atornilla el carro de altura al carro de la guía y la tuerca del husillo a su pestaña. Monta la guía MGN9 bajo la repisa, el motor de la guía y su polea sobre la repisa, y la polea tensora al frente.","<b>Guide.</b> Deburr and round both ends of the brass tube, press it into the guide arm, and bolt the arm under the MGN9 carriage. Loop the belt round the pulley and the idler and clamp both ends in the arm.":"<b>Guía.</b> Quita las rebabas y redondea ambos extremos del tubo de latón, insértalo a presión en el brazo guía y atornilla el brazo bajo el carro MGN9. Pasa la correa por la polea y la tensora y sujeta ambos extremos en el brazo.","<b>Thread path.</b> Fit the cone stand with its M8 bolt and the eyelet bracket above it, with the tension discs on their post. Fit the dancer bracket with the arm and the switch so the switch closes when the arm drops, and run the PTFE tube from the dancer to the guide arm. The thread goes up from the cone through the eyelet, between the discs, through the dancer eye and the tube.":"<b>Recorrido del hilo.</b> Monta el soporte del cono con su perno M8 y encima el soporte del ojal, con los discos de tensión en su eje. Monta el soporte del brazo tensor con el brazo y el interruptor, de modo que el interruptor se cierre cuando el brazo cae, y lleva el tubo de PTFE desde el brazo tensor hasta el brazo guía. El hilo sube desde el cono por el ojal, pasa entre los discos, por el ojo del brazo tensor y por el tubo.","<b>Switches and wiring.</b> Fit the home switches where the guide and the carriage reach them at the back and the top, then wire everything as in the diagram.":"<b>Interruptores y cableado.</b> Monta los interruptores de inicio donde la guía y el carro los alcanzan, atrás y arriba; luego cablea todo como en el diagrama.","<b>Flash GRBL 1.1</b> on the Uno and send the settings below, one line at a time, from any G-code sender.":"<b>Carga GRBL 1.1</b> en el Uno y envía los ajustes de abajo, una línea a la vez, desde cualquier programa emisor de G-code.","<b>Directions.</b> Jog each axis a little. X+ must turn the board anticlockwise seen from the front, Y+ move the guide towards the tower, Z+ raise it. Reverse an axis with $3 if it goes the wrong way.":"<b>Sentidos.</b> Mueve un poco cada eje. X+ debe girar el tablero en sentido antihorario visto de frente, Y+ llevar la guía hacia la torre y Z+ subirla. Invierte un eje con $3 si va al revés.","<b>Steps.</b> Mark the platter's edge and send G91 G1 X360 F600: the board must turn exactly once. Check Y and Z against a ruler.":"<b>Pasos.</b> Marca el borde del plato y envía G91 G1 X360 F600: el tablero debe dar exactamente una vuelta. Comprueba Y y Z con una regla.","<b>Homing.</b> Send $H. The guide rises, moves back to its switch, and the board turns until the magnet passes the sensor.":"<b>Punto de inicio.</b> Envía $H. La guía sube, retrocede hasta su interruptor y el tablero gira hasta que el imán pasa por el sensor.","<b>Work zero.</b> Clamp a board on, jog the guide's tip exactly above nail 0, just clear of its top, and send G10 L20 P1 X0 Y0 Z18 (18 = the nail height). GRBL remembers it.":"<b>Cero de trabajo.</b> Sujeta un tablero, lleva la punta de la guía justo encima del clavo 0, apenas por encima de su cabeza, y envía G10 L20 P1 X0 Y0 Z18 (18 = la altura del clavo). GRBL lo recuerda.","<b>Dry run.</b> Without thread, run the demo pattern's G-code at half speed (feed override 50 %). Watch the tube pass through the gaps and round the nails.":"<b>Prueba en vacío.</b> Sin hilo, ejecuta el G-code del patrón de demostración a media velocidad (ajuste de avance al 50 %). Observa cómo el tubo pasa por los huecos y rodea los clavos.","<b>Tension.</b> Tie the thread on and turn the tension discs' wing nut until the thread leaving the guide just lifts a 25 g weight (0.25 N; see Thread tension above). Then wind your first piece.":"<b>Tensión.</b> Ata el hilo y gira la tuerca de mariposa de los discos de tensión hasta que el hilo que sale de la guía apenas levante un peso de 25 g (0,25 N; mira Tensión del hilo más arriba). Luego enrolla tu primera pieza.","cut right through":"cortar de lado a lado","bearing, 305 mm":"rodamiento, 305 mm","Ø 20 access hole: mark through the bearing":"agujero de acceso de Ø 20: marcar a través del rodamiento","motor plate, underneath":"placa del motor, por debajo","hall sensor holder":"soporte del sensor Hall",tower:"torre",controller:"controlador","power supply":"fuente de alimentación","turntable axis":"eje de la plataforma","Base, 18 mm plywood, seen from above. All sizes in mm; holes Ø 4.5 unless marked.":"Base, contrachapado de 18 mm, vista desde arriba. Medidas en mm; agujeros de Ø 4,5 salvo indicación.","Drilling plan for the base":"Plano de taladrado de la base","nail board, Ø 640":"tablero de clavos, Ø 640","Ø 10 through, for the dowel":"Ø 10 pasante, para el pasador","turn buttons":"trabas giratorias","pulley, underneath":"polea, por debajo","magnet underneath: Ø 6, 3 deep":"imán por debajo: Ø 6, 3 de profundidad","Platter, 12 mm plywood, seen from above; dashed holes are drilled from underneath. Turn buttons every 120°, pulley screws every 60°.":"Plato, contrachapado de 12 mm, visto desde arriba; los agujeros punteados se taladran por debajo. Trabas cada 120°, tornillos de la polea cada 60°.","Drilling plan for the platter":"Plano de taladrado del plato","Arduino Uno + CNC Shield V3":"Arduino Uno + CNC Shield V3","X driver":"driver X","Y driver":"driver Y","Z driver":"driver Z","jumpers M0 + M1: 1/16 step":"puentes M0 + M1: 1/16 de paso","driver current about 0.8 A":"corriente del driver unos 0,8 A","Height motor":"Motor de altura","NEMA 17 + T8":"NEMA 17 + T8","Hall sensor A3144":"Sensor Hall A3144","5 V, GND, signal":"5 V, GND, señal","Y home switch":"Interruptor de inicio Y","normally open, to GND":"normalmente abierto, a GND","Z home switch":"Interruptor de inicio Z","closes when the dancer drops":"se cierra cuando cae el brazo tensor","Resume button (optional)":"Botón de reanudar (opcional)","to the shield's screw terminal":"a la bornera del shield",Computer:"Computadora","USB: G-code sender":"USB: emisor de G-code","GRBL 1.1 moves the Z limit to D12, the pin marked SpnEn on the CNC Shield V3; the Z+/Z− header does not work for it.":"GRBL 1.1 pasa el límite Z al pin D12, el marcado SpnEn en el CNC Shield V3; el conector Z+/Z− no sirve para eso.","Wiring diagram":"Diagrama de cableado","€ {v}":"€ {v}","Turntable drive":"Transmisión de la plataforma","{a} to {b} teeth: {r} : 1":"de {a} a {b} dientes: {r} : 1","Motor to turntable axis":"Del motor al eje de la plataforma","{c} mm, with a {l} mm belt; {m} teeth in mesh":"{c} mm, con una correa de {l} mm; {m} dientes engranados",Steps:"Pasos","X {x} per degree · Y {y} per mm · Z {z} per mm":"X {x} por grado · Y {y} por mm · Z {z} por mm","Smallest move of a nail":"Movimiento mínimo de un clavo","{u} µm per microstep":"{u} µm por micropaso","Motor speeds at top speed":"Velocidad de los motores a velocidad máxima","X {x} rpm · Y {y} rpm · Z {z} rpm":"X {x} rpm · Y {y} rpm · Z {z} rpm","Step pulses at top speed":"Pulsos de paso a velocidad máxima","{r} per second at most (GRBL on an Uno manages about {g})":"{r} por segundo como máximo (GRBL en un Uno llega a unos {g})","Turning load":"Carga que gira","{m} kg of platter and board, {i} kg·m²":"{m} kg de plato y tablero, {i} kg·m²","Torque at the motor":"Par en el motor","needs {n} N·m to accelerate, has about {a} N·m: {s} times the need":"necesita {n} N·m para acelerar y tiene unos {a} N·m: {s} veces lo necesario","Under the base":"Bajo la base","the motor hangs {h} mm down; the {f} mm feet leave {c} mm to the floor":"el motor cuelga {h} mm; las patas de {f} mm dejan {c} mm hasta el piso",Part:"Pieza","Size or type":"Medida o tipo",Qty:"Cant.",About:"Aprox.","Total, roughly":"Total aproximado","{g} g":"{g} g","Size, mm":"Medidas, mm",Filament:"Filamento","All printed parts":"Todas las piezas impresas","The list of printed parts could not be loaded.":"No se pudo cargar la lista de piezas impresas.",Copied:"Copiado",wood:"madera",printed:"impresa","bought metal parts":"piezas metálicas compradas",motors:"motores",electronics:"electrónica","thread path":"recorrido del hilo","Click a part to see what it is. Drag to turn, scroll to zoom.":"Haz clic en una pieza para ver qué es. Arrastra para girar, usa la rueda para acercar.","Loading the 3D model… {p} %":"Cargando el modelo 3D… {p} %","The 3D model could not be shown in this browser.":"No se pudo mostrar el modelo 3D en este navegador.",Board:"Tablero","Nail diameter":"Diámetro del clavo","Thicker nails leave a narrower gap for the guide.":"Los clavos más gruesos dejan un hueco más estrecho para la guía.","Nail height above the board":"Altura del clavo sobre el tablero","The wraps stack up the nails; taller nails hold more.":"Las vueltas se apilan en los clavos; los clavos más altos admiten más.","Thread guide":"Guía del hilo","Guide tube diameter":"Diámetro del tubo guía","The outside diameter of the tube tip that passes between the nails.":"El diámetro exterior de la punta del tubo que pasa entre los clavos.","Waits inside the ring by":"Espera dentro del aro a","How far inside the nail circle the guide waits while the board turns.":"Qué tan adentro del círculo de clavos espera la guía mientras gira el tablero.","Goes outside the ring by":"Sale del aro hasta","How far outside the nail circle the guide goes to wrap a nail.":"Qué tan afuera del círculo de clavos sale la guía para enrollar un clavo.","First wrap height":"Altura de la primera vuelta","The height of the first wrap on each nail, above the board.":"La altura de la primera vuelta en cada clavo, sobre el tablero.","Rise per wrap":"Subida por vuelta","Each later wrap on the same nail is laid this much higher. About the thread diameter.":"Cada vuelta posterior en el mismo clavo se coloca esta cantidad más arriba. Más o menos el diámetro del hilo.",Motion:"Movimiento","Board turning speed":"Velocidad de giro del tablero","Top turning speed of the turntable.":"Velocidad máxima de giro de la plataforma giratoria.","Board acceleration":"Aceleración del tablero","A heavy board needs a gentle acceleration, or the motor skips steps.":"Un tablero pesado necesita una aceleración suave; si no, el motor pierde pasos.","Guide speed":"Velocidad de la guía","Top speed of the guide moving in and out.":"Velocidad máxima de la guía al entrar y salir.","Guide acceleration":"Aceleración de la guía","Acceleration of the guide moving in and out.":"Aceleración de la guía al entrar y salir.","Height speed":"Velocidad de altura","Top speed of the guide moving up and down.":"Velocidad máxima de la guía al subir y bajar.","Height acceleration":"Aceleración de altura","Acceleration of the guide moving up and down.":"Aceleración de la guía al subir y bajar.","Thread speed":"Velocidad del hilo","The fastest the thread may be pulled off the spool. It limits how fast the board may turn.":"Lo más rápido que puede tirarse del hilo del carrete. Limita qué tan rápido puede girar el tablero.",Controller:"Controlador","Steps per degree (turn)":"Pasos por grado (giro)","Motor steps for one degree of board turn: 200 steps × microsteps × gear ratio ÷ 360.":"Pasos del motor por cada grado de giro del tablero: 200 pasos × micropasos × relación de transmisión ÷ 360.","Steps per mm (guide)":"Pasos por mm (guía)","Motor steps for one millimetre of guide travel.":"Pasos del motor por cada milímetro de recorrido de la guía.","Steps per mm (height)":"Pasos por mm (altura)","Motor steps for one millimetre of guide height.":"Pasos del motor por cada milímetro de altura de la guía.","Stop every":"Detenerse cada",lines:"líneas","The machine stops after this many lines so you can check the thread. 0 never stops.":"La máquina se detiene tras esta cantidad de líneas para que revises el hilo. Con 0 nunca se detiene.","Demo pattern: a star of 720 lines":"Patrón de demostración: una estrella de 720 líneas","{name} · {n} nails · {d} mm board · {t} mm thread · {l} lines":"{name} · {n} clavos · tablero de {d} mm · hilo de {t} mm · {l} líneas","{h} h {m} min":"{h} h {m} min","{m} min":"{m} min","The guide tube ({g} mm) passes between nails with a {gap} mm gap, leaving {s} mm on each side.":"El tubo guía ({g} mm) pasa entre clavos separados por un hueco de {gap} mm y le quedan {s} mm a cada lado.","That is too tight to pass reliably: use a thinner tube or thinner nails, fewer nails or a bigger board.":"Es demasiado justo para pasar de forma fiable: usa un tubo o clavos más delgados, menos clavos o un tablero más grande.","While the board turns, the guide waits {h} mm inside the nail circle, clear of the nails.":"Mientras gira el tablero, la guía espera {h} mm dentro del círculo de clavos, sin tocarlos.","The guide waits only {h} mm inside the nail circle and would hit the nails as the board turns: it needs at least {n} mm.":"La guía espera solo {h} mm dentro del círculo de clavos y chocaría con ellos al girar el tablero: necesita al menos {n} mm.","To wrap a nail the guide goes {h} mm outside the nail circle, clear of the nails.":"Para enrollar un clavo, la guía sale {h} mm fuera del círculo de clavos, sin tocarlos.","The guide goes only {h} mm outside the nail circle and would hit the nail it wraps: it needs at least {n} mm.":"La guía sale solo {h} mm fuera del círculo de clavos y chocaría con el clavo que enrolla: necesita al menos {n} mm.","The first wrap height is not below the top limit, 2 mm under the nail tops ({t} mm). Lower it or use taller nails.":"La altura de la primera vuelta no queda por debajo del límite superior, 2 mm bajo la punta de los clavos ({t} mm). Bájala o usa clavos más altos.","The busiest nail gets {w} wraps; the highest is laid {z} mm above the board, below the {t} mm limit.":"El clavo más usado recibe {w} vueltas; la más alta queda a {z} mm sobre el tablero, por debajo del límite de {t} mm.","{c} wraps would go higher and are laid at the limit, pressed onto earlier ones. Use taller nails or a smaller rise per wrap.":"{c} vueltas quedarían más arriba y se colocan en el límite, apretadas sobre las anteriores. Usa clavos más altos o una subida por vuelta menor.","No line rubs a neighbouring nail: the closest passes {w} mm clear.":"Ninguna línea roza un clavo vecino: la más cercana pasa a {w} mm.","{n} of {l} lines leave a nail at a shallow angle and rub the next nail, which pulls them slightly out of line (by up to {w} mm). Lines that skip at least {s} nails are clear; this piece's smallest skip is {m}. To avoid it, set the minimum nail skip in the app to {s}.":"{n} de {l} líneas salen de un clavo con un ángulo muy plano y rozan el clavo siguiente, lo que las desvía un poco (hasta {w} mm). Las líneas que saltan al menos {s} clavos no rozan; el salto más pequeño de esta pieza es {m}. Para evitarlo, pon el salto mínimo entre clavos de la aplicación en {s}.","The board turns at {v} °/s at most: any faster and the rim would pull thread off the spool faster than {t} mm/s.":"El tablero gira a {v} °/s como máximo: más rápido, el borde tiraría del hilo del carrete a más de {t} mm/s.","The board turns at up to {v} °/s.":"El tablero gira hasta {v} °/s.","Winding time (estimate, without stops)":"Tiempo de enrollado (estimado, sin paradas)","Per line, on average":"Por línea, en promedio","Machine moves":"Movimientos de la máquina","The board turns in all":"Vueltas totales del tablero","{n} turns":"{n} vueltas","Wraps on the busiest nail":"Vueltas en el clavo más usado","{m} m between nails, plus about {w} m round the nails":"{m} m entre clavos, más unos {w} m alrededor de los clavos","setting up":"preparando","turning to the nail":"girando hacia el clavo","setting the height":"ajustando la altura","guide out":"guía afuera",wrapping:"enrollando","guide in":"guía adentro",finished:"terminado","Line {k} of {l}":"Línea {k} de {l}","nail {a} → {b}":"clavo {a} → {b}",Play:"Reproducir","Your last result ({src})":"Tu último resultado ({src})","Your last result":"Tu último resultado","No result from the app in this browser yet, so here is a demo pattern. Make a piece in the app, or open a project file.":"Todavía no hay un resultado de la aplicación en este navegador, así que aquí tienes un patrón de demostración. Haz una pieza en la aplicación o abre un archivo de proyecto.","Finished.":"Terminado.","Line {n} of {t}":"Línea {n} de {t}","Done! Tie the thread off at nail {n}.":"¡Listo! Ata el final del hilo en el clavo {n}.","from nail {n}":"desde el clavo {n}","Portrait – fine":"Retrato – fino","Portrait – bold":"Retrato – marcado","High-contrast graphic":"Gráfico de alto contraste","300 nails, 0.2 mm thread, up to 4,500 lines: fine detail and soft tones. Takes longest to wind.":"300 clavos, hilo de 0,2 mm, hasta 4.500 líneas: detalle fino y tonos suaves. Es el que más tarda en enrollarse.","200 nails, 0.4 mm thread, up to 2,500 lines: strong shapes that read from across a room.":"200 clavos, hilo de 0,4 mm, hasta 2.500 líneas: formas fuertes que se leen desde el otro lado de una sala.","240 nails, dark thread and a length penalty: solid areas fill and edges near the rim stay crisp. For logos and silhouettes.":"240 clavos, hilo oscuro y penalización por longitud: las zonas sólidas se llenan y los bordes cerca del aro quedan nítidos. Para logotipos y siluetas.","Preset “{name}”: {tip}":"Preajuste «{name}»: {tip}","Your last result is shown again ({n} lines{src}). Load a picture to make a new one.":"Se muestra de nuevo tu último resultado ({n} líneas{src}). Carga una imagen para hacer uno nuevo.","Project loaded: the solver reproduced the saved sequence exactly ({n} lines).":"Proyecto cargado: el cálculo reprodujo exactamente la secuencia guardada ({n} líneas).","Project loaded, but this run differs from the saved sequence. It was probably saved with another version of the app.":"Proyecto cargado, pero este cálculo difiere de la secuencia guardada. Probablemente se guardó con otra versión de la aplicación.","That project file is damaged: its picture does not match its fingerprint.":"Ese archivo de proyecto está dañado: su imagen no coincide con su huella.","That project was saved by a newer version of the app.":"Ese proyecto se guardó con una versión más nueva de la aplicación.","That is not a String Art project file.":"Ese no es un archivo de proyecto de String Art.","String Art nail template · {n} nails · {d} mm board":"Plantilla de clavos de String Art · {n} clavos · tablero de {d} mm","100 mm × 100 mm: check with a ruler":"100 mm × 100 mm: compruébalo con una regla","row {r}, column {c}":"fila {r}, columna {c}","{n} pages of {paper} for a {d} mm board.":"{n} páginas {paper} para un tablero de {d} mm.","Print these pages at actual size (100 %, no scaling), check the 100 mm square with a ruler, then trim and tape the pages together, matching the crosses in the shaded overlaps.":"Imprime estas páginas a tamaño real (100 %, sin escalar), comprueba el cuadrado de 100 mm con una regla y luego recorta y une las páginas con cinta, haciendo coincidir las cruces de las franjas sombreadas que se solapan.","Sample portrait":"Retrato de ejemplo","The sample could not be loaded.":"No se pudo cargar el ejemplo.","{n}, numbered 0 to {m} clockwise; nail 0 at the top":"{n}, numerados del 0 al {m} en sentido horario; el clavo 0 arriba","{d} mm (the circle the nails stand on)":"{d} mm (el círculo sobre el que van los clavos)","{t} mm black; you need {m} m, plus {s} m for wrapping and slack":"negro de {t} mm; necesitas {m} m, más {s} m para las vueltas y la holgura",Start:"Inicio","tie the thread to nail {n}":"ata el hilo al clavo {n}","String Art — winding instructions":"String Art — instrucciones de enrollado","Made with String Art version {v} on {d}.":"Hecho con String Art versión {v} el {d}.","The finished piece, as simulated":"La pieza terminada, simulada","How to wind":"Cómo enrollar","Number the nails 0 to {m} clockwise, starting with nail 0 at the top (12 o'clock).":"Numera los clavos del 0 al {m} en sentido horario, empezando con el clavo 0 arriba (las 12 en punto).","Tie the thread to nail {n}.":"Ata el hilo al clavo {n}.","Read each block left to right: take the thread straight across the board to the next nail, once around it, and on to the next. Keep the thread taut.":"Lee cada bloque de izquierda a derecha: lleva el hilo en línea recta a través del tablero hasta el siguiente clavo, dale una vuelta y sigue al siguiente. Mantén el hilo tenso.","Tick a block when it is done. The ticks are remembered in this browser, so you can stop and carry on later.":"Marca un bloque cuando lo termines. Las marcas se recuerdan en este navegador, así que puedes parar y seguir más tarde.","After the last nail, tie the thread off.":"Después del último clavo, ata el final del hilo.","Print or save as PDF":"Imprimir o guardar como PDF","{n} of {t} blocks done":"{n} de {t} bloques terminados","Low contrast (spread {s}). String art draws with the differences between areas: with little contrast every line darkens everything about equally and the result is a grey haze. Raise the contrast, try the local contrast boost, or choose a picture with stronger lights and darks.":"Poco contraste (dispersión {s}). El arte con hilo dibuja con las diferencias entre zonas: con poco contraste cada línea oscurece todo casi por igual y el resultado es una bruma gris. Sube el contraste, prueba el refuerzo de contraste local o elige una imagen con luces y sombras más marcadas.","Busy border. Every line starts and ends at the rim, so detail or texture near the edge turns into clutter that crosses the whole picture. Zoom in on the subject or choose a plainer background.":"Borde recargado. Cada línea empieza y termina en el borde, así que el detalle o la textura cerca del borde se convierte en un desorden que cruza toda la imagen. Acércate al motivo o elige un fondo más liso.","Good contrast and a quiet border: this picture should work well.":"Buen contraste y un borde tranquilo: esta imagen debería funcionar bien.","{d}°":"{d}°","{p} % of the board":"{p} % del tablero","String Art version {v}":"String Art versión {v}","That file could not be read. Use a JPG, PNG or WebP picture.":"No se pudo leer ese archivo. Usa una imagen JPG, PNG o WebP.","The solver stopped with an error.":"El cálculo se detuvo por un error.","Preparing the lines…":"Preparando las líneas…","Line {n} of {k} · RMSE {e}":"Línea {n} de {k} · RMSE {e}","Paused.":"En pausa.","The solver stopped with an error: {e}":"El cálculo se detuvo por un error: {e}","Done: {n} lines, the most allowed.":"Listo: {n} líneas, el máximo permitido.","Done: {n} lines. More lines would not improve the picture.":"Listo: {n} líneas. Más líneas no mejorarían la imagen.","Done: {n} lines. Every allowed line from the last nail has been used.":"Listo: {n} líneas. Ya se usaron todas las líneas permitidas desde el último clavo.","Stopped after {n} lines.":"Detenido después de {n} líneas.","Pausing…":"Pausando…",Resume:"Seguir",Pause:"Pausa",Lines:"Líneas","RMSE (lower is better)":"RMSE (menor es mejor)","SSIM, pixel by pixel":"SSIM, píxel a píxel","SSIM, seen from a distance":"SSIM, visto a distancia",Thread:"Hilo","{m} m, plus {s} m for wrapping and slack":"{m} m, más {s} m para las vueltas y la holgura",Time:"Tiempo","{s} s":"{s} s","Line cache":"Caché de líneas","all lines precomputed, {mb} MB":"todas las líneas precalculadas, {mb} MB","lines computed as needed":"líneas calculadas cuando hacen falta","Board diameter":"Diámetro del tablero","Diameter of the nail circle on the real board. A bigger board shows finer detail and uses more thread.":"Diámetro del círculo de clavos en el tablero real. Un tablero más grande muestra más detalle y usa más hilo.",Nails:"Clavos","How many nails around the circle. More nails give finer detail but take longer to wind.":"Cuántos clavos hay alrededor del círculo. Más clavos dan más detalle, pero lleva más tiempo enrollar el hilo.","Thread diameter":"Grosor del hilo","Thicker thread darkens faster: each line covers more of the board. At least 0.15 mm, so the winding machine cannot break it.":"El hilo más grueso oscurece más rápido: cada línea cubre más del tablero. Al menos 0,15 mm, para que la máquina de enrollar no pueda romperlo.","Most lines":"Máximo de líneas","The most lines to wind. The solver stops earlier if no line improves the picture any more.":"El máximo de líneas a enrollar. El cálculo se detiene antes si ninguna línea mejora ya la imagen.","Minimum nail skip":"Salto mínimo entre clavos","No line may join nails closer than this. Short lines near the rim only add clutter.":"Ninguna línea puede unir clavos más cercanos que esto. Las líneas cortas junto al borde solo ensucian.","Uses per line":"Usos por línea","How many times the thread may join the same two nails.":"Cuántas veces el hilo puede unir los mismos dos clavos.","Start nail":"Clavo inicial","The nail where the thread is tied on. Nail 0 is at the top; numbers run clockwise.":"El clavo donde se ata el hilo. El clavo 0 está arriba; la numeración va en sentido horario.","Working resolution":"Resolución de trabajo","Size of the picture the solver compares against, in pixels. Higher is more precise but slower and uses more memory.":"Tamaño de la imagen con la que compara el cálculo, en píxeles. Más alta es más precisa, pero más lenta y usa más memoria.","Darkness factor":"Factor de oscuridad","How dark one pass of thread counts. Above 1 the solver reaches the same darkness with fewer lines; below 1 it uses more.":"Cuánto oscurece una pasada de hilo. Por encima de 1 el cálculo logra la misma oscuridad con menos líneas; por debajo de 1 usa más.","Length penalty β":"Penalización por longitud β","Above 0, long lines count for less: a line's score is divided by its length to this power. It brings out detail near the edge.":"Por encima de 0, las líneas largas cuentan menos: la puntuación de una línea se divide entre su longitud elevada a esta potencia. Resalta el detalle cerca del borde.","Stop threshold ε":"Umbral de parada ε","Stop once the best line improves the picture by less than this for 20 lines in a row. 0 stops when lines stop helping.":"Se detiene cuando la mejor línea mejora la imagen menos que esto durante 20 líneas seguidas. Con 0 se detiene cuando las líneas dejan de ayudar.","What does this do?":"¿Qué hace esto?"},H:{"calc.title":"String Art — Cálculos","calc.meta":"Con qué fuerza tira del hilo la máquina de enrollar, qué lo limita y qué tan delgado puede ser el hilo: cada paso con su fórmula y los números puestos, para tu propia máquina y pieza.","calc.sub":"cálculos","calc.h1":"Cálculos: tensión del hilo","calc.intro":"La fuerza con que la máquina de enrollar tira del hilo decide si los clavos más usados se doblan y qué tan delgado puede ser el hilo. Cambia los números de abajo por los de tu máquina y tu pieza: cada paso se vuelve a calcular.","calc.h.inputs":"Tus números","calc.reset":"Los valores de la máquina","bd.calcLink":"Todos los cálculos","nav.calc":"Cálculos","bd.h.tension":"Tensión del hilo","wd.h":"Enróllalo con tu máquina","wd.noSerial":"Para manejar la máquina hace falta Chrome o Edge en una computadora: pueden hablar con su controlador por USB. Igual puedes descargar el G-code y enviarlo con cualquier programa emisor de G-code.","wd.connect":"Conectar la máquina","wd.h.setup":"Preparar","wd.home":"Ir al inicio","wd.unlock":"Desbloquear","wd.settings":"Enviar los ajustes","wd.prevNail":"◀ un clavo","wd.nextNail":"un clavo ▶","wd.in":"◀ adentro","wd.out":"afuera ▶","wd.down":"▼ bajar","wd.up":"subir ▲","wd.zero":"La guía está sobre el clavo 0: fijar el cero","wd.h.wind":"Enrollar","wd.from":"Desde la línea","wd.start":"Empezar","wd.pause":"Pausa","wd.resume":"Reanudar","wd.stop":"Detener","wd.back":"Retroceder","wd.lines":"líneas","wd.backBtn":"Retroceder","wd.speed":"Velocidad","wd.console":"Consola del controlador","wd.send":"Enviar","wd.disconnect":"Desconectar","wd.jog":"Mover a mano","wd.step":"Paso de movimiento","wd.cmdHint":"Un comando G-code o $","bd.title":"String Art — Construye la máquina de enrollar","bd.meta":"Construye la máquina de enrollar de String Art: un modelo 3D, las piezas que comprar, piezas para imprimir, planos de taladrado, cableado, ajustes del controlador y el montaje paso a paso.","bd.sub":"construye la máquina","bd.toMachine":"Máquina","bd.h1":"Construye la máquina de enrollar","bd.intro":"Una plataforma giratoria lleva el tablero de clavos; una guía de hilo sobre su borde solo se mueve hacia adentro y afuera, y hacia arriba y abajo. Todo aquí se calcula a partir de un único conjunto de medidas, para un círculo de clavos de 600 mm con 240 clavos: el modelo 3D, las piezas impresas, los planos de taladrado y los ajustes del controlador. La página de la máquina planifica los movimientos y escribe el G-code.","bd.loading":"Cargando el modelo 3D…","bd.pickHint":"Haz clic en una pieza para ver qué es. Arrastra para girar, usa la rueda para acercar.","bd.turn":"Girar despacio","bd.h.numbers":"Los números","bd.h.buy":"Piezas que comprar","bd.h.print":"Piezas que imprimir","bd.printHint":"Cada archivo está girado en la posición en que mejor se imprime y apoyado en la cama. Capas de 0,2 mm salvo que la nota diga otra cosa. El modelo de FreeCAD contiene todas las piezas y se puede modificar.","bd.fcstd":"Modelo de FreeCAD (.FCStd)","bd.h.drill":"Planos de taladrado","bd.svgBase":"Plano de la base a tamaño real (SVG)","bd.svgPlatter":"Plano del plato a tamaño real (SVG)","bd.svgHint":"Los archivos a tamaño real están en milímetros: imprímelos al 100 % (la mayoría de los visores de PDF pueden dividir una página grande en mosaicos) o úsalos para marcar. El tablero de clavos usa la plantilla de clavos de la aplicación.","bd.h.wiring":"Cableado","bd.h.grbl":"Ajustes del controlador","bd.grblHint":"Envíalos una vez a GRBL 1.1 desde cualquier programa emisor de G-code; GRBL los guarda.","bd.copy":"Copiar los ajustes","bd.h.assembly":"Montaje","bd.h.calibrate":"Puesta a punto y primera prueba","mc.build":"Construirla","mc.buildBtn":"Construye la máquina: piezas, planos y cableado","mc.zoomLabel":"Primer plano de la guía y el clavo que se enrolla","mc.zoomCap":"primer plano, tamaño real","nav.machine":"Máquina","dl.machine":"Enrollarlo con una máquina","mc.title":"String Art — Máquina de enrollar","mc.meta":"Enrolla una pieza de String Art con una máquina: un tablero que gira y una guía para el hilo. Comprueba la máquina con la pieza, estima el tiempo de enrollado, mírala enrollar y descarga el G-code.","mc.sub":"máquina de enrollar","mc.back":"← Volver a la aplicación","mc.h.piece":"La pieza","mc.demo":"Patrón de demostración","mc.pieceHint":"La máquina enrolla tu último resultado de la aplicación en este navegador, o un archivo de proyecto. Los clavos, el tablero y el hilo vienen de la pieza.","mc.h.machine":"La máquina","mc.reset":"Ajustes recomendados","mc.play":"Reproducir","mc.restart":"Desde el principio","mc.speed":"Velocidad de reproducción","mc.upright":"Mantener la imagen derecha","mc.canvas":"La máquina vista de frente: el tablero gira bajo una guía de hilo fija arriba","mc.scrub":"Línea","mc.gcode":"Descargar G-code","mc.gcodeHint":"Para GRBL (o Marlin) con tres ejes. El archivo empieza con los ajustes del controlador y los pasos de preparación; se detiene para que ates el hilo al principio y al final.","mc.h.checks":"Comprobaciones","mc.h.summary":"Enrollado","mc.h.how":"Cómo enrolla la máquina","mc.how1":"El tablero descansa sobre una plataforma giratoria. Sobre su borde hay una guía de hilo, un tubo delgado por el que pasa el hilo desde un carrete con freno; la guía solo se mueve hacia adentro y hacia afuera a lo largo de un radio, y hacia arriba y abajo. Para enrollar una línea hasta el clavo siguiente:","mc.step1":"<b>Girar.</b> El tablero gira hasta que el hueco junto al clavo siguiente queda bajo la guía. La guía espera justo dentro del aro, así que el hilo desde el último clavo cruza el centro despejado y no puede engancharse.","mc.step2":"<b>Afuera.</b> La guía sale por el hueco, más allá de los clavos.","mc.step3":"<b>Enrollar.</b> El tablero gira un clavo, que pasa junto a la guía, así que el hilo queda por detrás de él.","mc.step4":"<b>Adentro.</b> La guía vuelve a entrar por el hueco del otro lado. El hilo queda enrollado en el clavo y el freno del carrete lo tensa.","mc.how2":"Cada vuelta posterior en el mismo clavo se coloca un poco más arriba, para que se apilen de forma ordenada. Los ejes del G-code: X es el giro del tablero en grados, Y la distancia de la guía al círculo de clavos en mm (negativa por dentro) y Z su altura sobre el tablero.","about.h.math":"Las matemáticas detrás","about.m.intro":"Aquí está cada paso que da la aplicación, con las ecuaciones que usa. Solo necesitas potencias, raíces cuadradas, seno y coseno, y el signo Σ, que significa «súmalos todos».","about.m1.h":"1. De una foto a un mapa de oscuridad","about.m1.a":"Una foto guarda cada píxel como tres números entre 0 y 1, para el rojo, el verde y el azul. Pero esos números están “aplastados”: las pantallas guardan la luz siguiendo una curva, para que los tonos oscuros reciban más números. Antes de hacer cuentas con la luz, la aplicación deshace la curva y obtiene la cantidad real de luz <i>L</i> a partir del valor guardado <i>v</i>:","about.m1.e1":"<i>L</i> = ((<i>v</i> + 0.055) / 1.055)<sup>2.4</sup>      (para valores muy oscuros: <i>L</i> = <i>v</i> / 12.92)","about.m1.b":"Nuestros ojos ven el verde mucho más claro que el rojo, y el azul como el más oscuro de los tres, así que el brillo <i>Y</i> de un píxel es un promedio ponderado:","about.m1.e2":"<i>Y</i> = 0.2126 <i>R</i> + 0.7152 <i>G</i> + 0.0722 <i>B</i>","about.m1.c":"El hilo es negro, así que la aplicación necesita lo contrario del brillo: cuán oscuro debe ser cada punto. Esa es la oscuridad objetivo <i>T</i>, de 0 (blanco, sin hilo) a 1 (negro, totalmente cubierto):","about.m1.e3":"<i>T</i> = 1 − <i>Y</i>","about.m1.d":"¿Por qué deshacer la curva? Porque el hilo funciona con luz real: un punto medio cubierto por hilo negro devuelve la mitad de la luz, y solo los números de luz real se suman así.","about.m2.h":"2. Dónde van los clavos","about.m2.a":"Hay <i>N</i> clavos repartidos por igual en un círculo de radio <i>R</i> alrededor del centro (<i>c</i><sub>x</sub>, <i>c</i><sub>y</sub>). El clavo 0 está arriba y la numeración va en sentido horario. El clavo <i>i</i> está en el ángulo","about.m2.e1":"<i>θ</i><sub><i>i</i></sub> = −90° + 360° · <i>i</i> / <i>N</i>","about.m2.b":"y su posición sale del coseno y el seno. En una pantalla la <i>y</i> crece hacia abajo, y por eso la numeración va en sentido horario:","about.m2.e2":"<i>x</i><sub><i>i</i></sub> = <i>c</i><sub>x</sub> + <i>R</i> cos <i>θ</i><sub><i>i</i></sub>      <i>y</i><sub><i>i</i></sub> = <i>c</i><sub>y</sub> + <i>R</i> sen <i>θ</i><sub><i>i</i></sub>","about.m2.c":"Una línea entre dos clavos separados por <i>d</i> lugares es una cuerda del círculo. En un tablero de diámetro <i>D</i> mide:","about.m2.e3":"longitud = <i>D</i> · sen(180° · <i>d</i> / <i>N</i>)","about.m2.d":"Por ejemplo, con 240 clavos en un tablero de 600 mm, los clavos 0 y 120 están uno frente al otro: sen(90°) = 1, así que la línea mide los 600 mm completos. Los clavos 0 y 60 están a un cuarto de vuelta: 600 · sen(45°) ≈ 424 mm.","about.m3.h":"3. Dibujar una línea en una cuadrícula de píxeles","about.m3.a":"Una línea recta rara vez pasa justo por el centro de los píxeles. La aplicación usa el método de Xiaolin Wu: recorre la línea columna por columna y, donde la línea pasa entre dos píxeles, reparte la tinta entre ellos. Si la línea está a una fracción <i>f</i> del camino entre el centro del píxel de arriba y el de abajo, reciben","about.m3.e1":"<i>w</i><sub>arriba</sub> = 1 − <i>f</i>      <i>w</i><sub>abajo</sub> = <i>f</i>","about.m3.b":"así que cada columna recibe siempre exactamente un píxel de tinta. Pero una línea inclinada es más larga que el número de columnas que cruza: una línea a 45° que cruza 100 columnas mide 141 píxeles. Por eso cada línea recibe una corrección","about.m3.e2":"<i>k</i> = longitud / columnas cruzadas      (entre 1 y √2 ≈ 1.41)","about.m4.h":"4. Cómo oscurece el hilo el tablero","about.m4.a":"Una pasada de hilo cubre solo una parte de un píxel. Al tamaño de trabajo, un píxel mide 600 mm / 700 ≈ 0.86 mm de ancho y el hilo 0.25 mm de grosor, así que una pasada cubre más o menos esta fracción (el factor de oscuridad, un ajuste, permite que el hilo cuente como más oscuro o más claro):","about.m4.e1":"<i>α</i> = (ancho del hilo / ancho del píxel) × factor de oscuridad = 0.25 / 0.86 × 1 ≈ 0.29","about.m4.b":"En un píxel de una línea con parte de tinta <i>w</i>, una pasada cubre <i>a</i> = <i>α</i> · <i>k</i> · <i>w</i> (nunca más de 1). Ahora la idea clave: un hilo nuevo que queda encima de los anteriores tapa la misma fracción del blanco que <b>todavía se ve</b>. Si <i>C</i> es lo oscuro que ya está un píxel, el blanco que se ve es 1 − <i>C</i>, y después de una pasada más","about.m4.e2":"1 − <i>C</i><sub>nuevo</sub> = (1 − <i>C</i>) · (1 − <i>a</i>)","about.m4.c":"Por tanto, después de <i>n</i> pasadas sobre un píxel blanco la oscuridad es","about.m4.e3":"<i>C</i> = 1 − (1 − <i>a</i>)<sup><i>n</i></sup>","about.m4.d":"Con <i>a</i> = 0.29: una pasada da 0.29, dos dan 0.50 (no 0.58), tres dan 0.64, diez dan 0.97. Los cruces se oscurecen cada vez más, pero nunca más que el negro, igual que el hilo real.","about.m5.h":"5. Elegir la siguiente línea","about.m5.a":"La aplicación mide cuánto se aleja su tablero simulado <i>C</i> del objetivo <i>T</i> con el error cuadrático: para cada píxel toma la diferencia, la eleva al cuadrado (así lo demasiado oscuro y lo demasiado claro cuentan los dos como positivo), la multiplica por la importancia de ese píxel (<i>W</i>, del pincel: 1 normalmente, hasta 3 en las zonas importantes) y lo suma todo:","about.m5.e1":"<i>E</i> = Σ <i>W</i> · (<i>T</i> − <i>C</i>)<sup>2</sup>","about.m5.b":"Enrollar una línea más oscurece cada uno de sus píxeles en <i>δ</i> = <i>a</i> · (1 − <i>C</i>). ¿Cuánto baja eso el error? Desarrollando (<i>T</i> − <i>C</i>)<sup>2</sup> − (<i>T</i> − <i>C</i> − <i>δ</i>)<sup>2</sup> se obtiene la mejora que aporta la línea:","about.m5.e2":"Δ<i>E</i> = Σ<sub>píxeles de la línea</sub> <i>W</i> · <i>δ</i> · (2(<i>T</i> − <i>C</i>) − <i>δ</i>)","about.m5.c":"Un píxel ayuda mientras todavía está más claro de lo que debería por más de la mitad de <i>δ</i>; cuando ya está bastante oscuro, más hilo ahí cuenta en contra de la línea. Desde el clavo donde está el hilo, la aplicación calcula Δ<i>E</i> para cada línea que puede enrollar a continuación (unas 200), enrolla la que tiene el Δ<i>E</i> más grande y repite desde el otro extremo de esa línea.","about.m5.d":"Esto se llama un método <b>voraz</b>: siempre toma el mejor paso siguiente y nunca mira más adelante. ¿Por qué no buscar la mejor secuencia de todas? Con 200 opciones en cada uno de 3.000 pasos hay 200<sup>3000</sup> secuencias posibles, un número de unas 6.900 cifras. Ninguna computadora podría probarlas todas; el método voraz solo necesita 200 × 3.000 = 600.000 puntuaciones, lo que tarda unos segundos.","about.m6.h":"6. Cuándo parar, y favorecer las líneas cortas","about.m6.a":"La aplicación se detiene después del máximo de líneas que permitas, o cuando el mejor Δ<i>E</i> ha estado por debajo de un umbral pequeño <i>ε</i> (normalmente 0) durante 20 líneas seguidas: entonces ninguna línea ayuda ya, y esas últimas 20 líneas se quitan. La penalización por longitud <i>β</i> divide la puntuación de cada línea entre su longitud <i>ℓ</i> elevada a una potencia:","about.m6.e1":"puntuación = Δ<i>E</i> / <i>ℓ</i><sup><i>β</i></sup>","about.m6.b":"Con <i>β</i> = 0 no cambia nada; con <i>β</i> = 1 una línea el doble de larga necesita el doble de mejora para ganar, lo que da más oportunidades a las líneas cortas cerca del borde.","about.m7.h":"7. Medir el resultado","about.m7.a":"La raíz del error cuadrático medio promedia las diferencias al cuadrado sobre los <i>n</i> píxeles del círculo y saca la raíz cuadrada, así que queda en las mismas unidades que la oscuridad (0 es perfecto):","about.m7.e1":"RMSE = √( Σ (<i>T</i> − <i>C</i>)<sup>2</sup> / <i>n</i> )","about.m7.b":"El SSIM (similitud estructural) compara pequeños parches de 7 × 7 de las dos imágenes: su oscuridad media <i>μ</i>, cuánto varían (<i>σ</i>) y cuánto varían juntos (<i>σ</i><sub>TC</sub>). Vale 1 cuando los parches coinciden y casi 0 cuando no tienen nada en común:","about.m7.e2":`SSIM = (2<i>μ</i><sub>T</sub><i>μ</i><sub>C</sub> + <i>c</i><sub>1</sub>)(2<i>σ</i><sub>TC</sub> + <i>c</i><sub>2</sub>) / ((<i>μ</i><sub>T</sub><sup>2</sup> + <i>μ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>1</sub>)(<i>σ</i><sub>T</sub><sup>2</sup> + <i>σ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>2</sub>))
<i>c</i><sub>1</sub> = 0.0001, <i>c</i><sub>2</sub> = 0.0009`,"about.m7.c":"Los números pequeños <i>c</i><sub>1</sub> y <i>c</i><sub>2</sub> evitan dividir entre cero en parches lisos. De cerca, el hilo es un enredo de líneas finas, así que la aplicación también da el SSIM después de desenfocar un poco las dos imágenes, más cercano a lo que ves a unos pasos. Por último, el hilo que necesitas es la suma de todas las longitudes de las líneas del paso 2, más un 10 % para las vueltas a los clavos y la holgura.","about.m8.h":"8. Ajustar la imagen","about.m8.a":"El contraste y el brillo actúan sobre el valor guardado <i>v</i>: el contraste <i>s</i> lo estira alejándolo del gris medio, el brillo <i>b</i> lo desplaza y la gamma <i>γ</i> lo curva, oscureciendo los tonos medios cuando <i>γ</i> es mayor que 1:","about.m8.e1":"<i>v</i>′ = ((<i>v</i> − 0.5) · <i>s</i> + 0.5 + <i>b</i>)<sup><i>γ</i></sup>","about.m8.b":"El refuerzo de contraste local (CLAHE) corta la imagen en una cuadrícula de 8 × 8 cuadrados. En cada cuadrado cuenta cuántos píxeles tienen cada tono (un histograma) y le da a cada tono un nuevo valor: la fracción de los píxeles del cuadrado que son más oscuros que él. Los tonos que comparten muchos píxeles se separan, así que aparece detalle en las zonas planas. Antes, cada cuenta se limita a un tope para no exagerar el ruido, y los cuadrados vecinos se mezclan para que no se noten las uniones.","tm.help":"Espacio, Intro o → para el siguiente clavo; ← para volver; Esc para cerrar. Tu posición se guarda en cada paso, así que puedes cerrar esto y seguir más tarde.","tm.nextBtn":"Siguiente ▶","tm.go":"Ir","tm.goto":"Ir a la línea","tm.back":"◀ Atrás","tm.board":"El tablero, con las líneas enrolladas hasta ahora y la siguiente línea resaltada","tm.after":"Después","tm.before":"Antes","tm.next":"Siguiente clavo","tm.close":"Cerrar","tm.full":"Pantalla completa","tm.speak":"Decir el clavo en voz alta","tm.title":"Modo de enhebrado","h.presets":"Preajustes","dl.thread":"Modo de enhebrado","in.project":"Abrir un proyecto","in.projNote":"Un proyecto guarda la imagen tal como la vio el cálculo, no la foto original. Para cambiar el recorte, los ajustes o las marcas del pincel, vuelve a subir la foto.","h.template":"Plantilla de clavos","tpl.hint":"Las posiciones de los clavos a tamaño real, numeradas, para pegar sobre el tablero. Imprime a tamaño real (100 %, no “ajustar a la página”) y comprueba el cuadrado de 100 mm con una regla.","tpl.paper":"Papel","tpl.pages":"Páginas para imprimir","tpl.svg":"Una sola hoja (SVG)","dl.png":"Vista previa (PNG)","dl.project":"Archivo del proyecto","dl.instructions":"Descargar las instrucciones de enrollado","dl.csv":"Secuencia (CSV)","brush.hint":"Pinta sobre la vista Objetivo. Las zonas cálidas cuentan hasta tres veces más y atraen más líneas; las frías cuentan apenas una quinta parte. Úsalo para los ojos, una boca o un borde que importe.","brush.clear":"Borrar las marcas del pincel","brush.size":"Tamaño del pincel","brush.down":"Menos importante","brush.up":"Más importante","brush.off":"Apagado","h.brush":"Pincel de importancia","h.seen":"Como la ve el cálculo","adj.reset":"Restablecer los ajustes","adj.clip":"Límite de recorte (más alto refuerza más)","adj.clahe":"Refuerzo de contraste local (CLAHE)","adj.gamma":"Gamma (por encima de 1 oscurece los medios tonos)","adj.contrast":"Contraste","adj.brightness":"Brillo","h.adjust":"Ajustar","crop.reset":"Restablecer el recorte","crop.rotate":"Girar","crop.zoom":"Acercar","crop.hint":"Arrastra para mover la imagen; usa la rueda o pellizca para acercar.","crop.label":"La imagen bajo el círculo del tablero: arrastra para moverla, usa la rueda o pellizca para acercar",title:"String Art — Un hilo, una imagen",meta:"Convierte una imagen en arte con hilo: un solo hilo continuo enrollado entre clavos en un marco circular. La aplicación encuentra el orden de clavos que mejor reproduce la imagen y muestra una vista previa realista, todo en tu navegador.",sub:"un hilo, una imagen","nav.about":"Acerca de","nav.projects":"← Todos los proyectos","h.picture":"Imagen","in.upload":"Subir una imagen","in.sample":"Usar el ejemplo","in.thumb":"La imagen como la ve el cálculo","in.hint":"Elige una imagen: un rostro u objeto con fuerte contraste sobre un fondo liso funciona mejor. No se sube nada a ningún sitio; todo se ejecuta en tu navegador.","h.params":"Parámetros","run.run":"Calcular","run.pause":"Pausa","run.cancel":"Cancelar","view.label":"Mostrar","view.thread":"Hilo","view.target":"Objetivo","view.both":"Lado a lado","view.threadLabel":"Vista previa del hilo sobre el tablero","view.threadCap":"hilo, dibujado con su grosor real","view.targetLabel":"El objetivo al que apunta el cálculo","view.targetCap":"oscuridad objetivo","h.metrics":"Resultado","log.summary":"Registro del cálculo","about.title":"Acerca de String Art","about.back":"← Volver a la aplicación","about.h1":"Acerca de String Art","about.p1":"String Art convierte una imagen en instrucciones para una artesanía clásica: clavos alrededor de un tablero circular y un solo hilo negro enrollado de clavo en clavo, miles de veces, hasta que los cruces del hilo dibujan la imagen. La aplicación calcula el orden de los clavos y muestra cómo se verá la pieza terminada.","about.h.how":"Cómo elige las líneas","about.how":"La imagen se convierte en un mapa de cuán oscuro debe ser cada punto. Partiendo de un clavo, la aplicación prueba cada línea que puede enrollar a continuación y se queda con la que acerca más el tablero simulado a ese mapa; luego sigue desde donde termina esa línea. El hilo oscurece el tablero como lo hace un hilo real: cada pasada tapa una fracción del blanco que aún se ve, así que los cruces se oscurecen, pero nunca más que el negro. Se detiene al llegar al máximo de líneas que permitas o cuando ninguna línea mejora ya la imagen.","about.h.numbers":"Los números","about.numbers":"El RMSE mide cuánto se aleja el tablero simulado del objetivo, píxel a píxel (0 es una coincidencia perfecta). El SSIM compara brillo, contraste y estructura locales (1 es idéntico); como el hilo es una textura fina de líneas, la aplicación también da el SSIM tras un ligero desenfoque, más cercano a lo que ves a unos pasos. La longitud del hilo es la suma de todas las líneas, con un 10 % más para las vueltas a los clavos y la holgura.","about.h.private":"Tus imágenes se quedan contigo","about.private":"Todo se ejecuta en tu navegador. Las imágenes nunca se suben.","about.h.status":"Qué hace","about.status":"Versión 1.0. Prepara la imagen —recórtala, acércala y gírala, ajusta brillo, contraste y gamma, refuerza el contraste local y pinta lo que importa— con una comprobación que avisa de las imágenes que no funcionarán bien; elige un preajuste o ajusta cada parámetro; y mira cómo se enrolla el hilo. Luego imprime la plantilla de clavos a tamaño real y las instrucciones de enrollado, y enrolla la pieza con el modo de enhebrado, que muestra (y puede decir) el siguiente clavo y recuerda dónde vas. Tus ajustes y tu último resultado se recuerdan en este navegador."}},c={T:{"tension discs":"spændeskiver","leaves the tip at":"forlader spidsen med","tension in the thread":"spænding i tråden","Tension along the thread path":"Spænding langs trådens vej","The tension grows at each bend: the discs give {b} N, the bends multiply it by {k} in all.":"Spændingen vokser ved hver bøjning: skiverne giver {b} N, og bøjningerne ganger den med {k} i alt.","last nail":"sidste søm",guide:"guide","Δ only grows during a turn (0 to 180°), so L only grows:":"Δ vokser kun under en drejning (0 til 180°), så L vokser kun:","the thread is always being pulled, never pushed back.":"tråden bliver altid trukket, aldrig skubbet tilbage.","Payout geometry":"Geometrien for trådudtræk","Seen from the board, the guide runs round the rim; the line from the last nail to the guide is what pulls thread off the cone.":"Set fra pladen løber guiden rundt langs kanten; linjen fra det sidste søm til guiden er det, der trækker tråd af keglen.","board speed ω":"pladens hastighed ω","thread payout speed dL/dt":"trådens udtræksfart dL/dt","thread payout acceleration d²L/dt²":"trådens udtræksacceleration d²L/dt²","time, s":"tid, s","Acceleration diagram":"Accelerationsdiagram","One 120° turn of the board, from the last nail, with the machine's own speed and acceleration. The thread's speed peaks at {v} m/s and its acceleration at {a} m/s², both inside the bounds R·ω and R·α the working uses. When the board brakes, the thread slows down ({d} m/s²): a spool turning on a pin would overrun and throw slack, a standing cone cannot.":"En drejning af pladen på 120° fra det sidste søm, med maskinens egen fart og acceleration. Trådens fart topper ved {v} m/s og accelerationen ved {a} m/s², begge inden for grænserne R·ω og R·α, som udregningen bruger. Når pladen bremser, sænker tråden farten ({d} m/s²): en spole, der drejer på en tap, ville løbe videre og give slap tråd; en stående kegle kan ikke.","Spool turning on a pin, felt brake":"Spole, der drejer på en tap, filtbremse","brake M":"bremse M","Standing cone, tension discs":"Stående kegle, spændeskiver",eyelet:"øje",balloon:"ballon",spring:"fjeder","disc friction":"skivefriktion","The spool's forces":"Kræfterne på spolen","On a pin, the brake's torque divides by a radius that shrinks as the spool empties, and the spool's inertia adds {i} N. On a standing cone nothing turns: the tension comes from the discs alone.":"På en tap divideres bremsens moment med en radius, der skrumper, mens spolen tømmes, og spolens inerti lægger {i} N til. På en stående kegle drejer intet: spændingen kommer alene fra skiverne.","Sag of the longest line":"Nedhæng på den længste linje","A line sags until the tension's slight downward tilt at each end carries its weight. The sag is drawn hundreds of times larger: at {t} N it is {s} mm.":"En linje synker, til spændingens svage hældning nedad i hver ende bærer dens vægt. Nedhænget er tegnet flere hundrede gange større: ved {t} N er det {s} mm.","Seen from above":"Set ovenfra",resultant:"resultant","Seen from the side":"Set fra siden",board:"plade","Forces on the busiest nail":"Kræfter på det mest brugte søm","Each wrap's two legs pull into the board; their sideways parts mostly cancel and the inward parts add up to F. F acts {h} mm above where the nail is held, bending it: the steel must not yield.":"Hver viklings to stykker trækker ind mod pladen; sideandelene ophæver for det meste hinanden, og de indadgående andele lægges sammen til F. F virker {h} mm over der, hvor sømmet holdes, og bøjer det: stålet må ikke give efter.",window:"vindue","no window":"intet vindue","straight lines":"lige linjer","nail bends":"sømmet bøjer",set:"indstillet","peak, cone":"top, kegle","peak, spool on pin":"top, spole på tap","The tension window":"Spændingsvinduet","The tension must sit between what keeps lines straight and what bends the busiest nail. The peaks show why the thread stands on a cone.":"Spændingen skal ligge mellem det, der holder linjerne lige, og det, der bøjer det mest brugte søm. Toppene viser, hvorfor tråden står på en kegle.","needed, standing cone":"nødvendig, stående kegle","needed, spool on a pin":"nødvendig, spole på tap","app minimum":"appens minimum","your thread":"din tråd","thread diameter, mm":"trådens diameter, mm","breaking strength, N":"brudstyrke, N","Thread strength against diameter":"Trådstyrke mod diameter","Strength grows with the square of the diameter. Where a fibre's curve crosses a dashed line is the thinnest thread of that fibre that is safe.":"Styrken vokser med diameteren i anden. Hvor en fibers kurve krydser en stiplet linje, ligger den tyndeste sikre tråd af den fiber.","Straight lines need at least {m} N.":"Lige linjer kræver mindst {m} N.","The busiest nail ({n} wraps, {d} mm) bends above about {l} N.":"Det mest brugte søm ({n} viklinger, {d} mm) bøjer over ca. {l} N.","The thread breaks at about {b} N and should hold {r} N.":"Tråden knækker ved ca. {b} N og bør holde {r} N.","The app's thinnest thread is {d} mm.":"Appens tyndeste tråd er {d} mm.","These numbers work: {t} N is inside the window.":"Disse tal virker: {t} N ligger inden for vinduet.","Something needs changing:":"Noget skal ændres:","The machine winds at {t} N: enough for straight lines (at least {a} N), below what bends the busiest nail (about {b} N with 1.5 mm nails and {n} wraps). It stands the thread on a cone with tension discs, and the thread must be at least {d} mm. Every step, with your own numbers, is on the calculations page.":"Maskinen vikler ved {t} N: nok til lige linjer (mindst {a} N) og under det, der bøjer det mest brugte søm (ca. {b} N med søm på 1,5 mm og {n} viklinger). Tråden står på en kegle med spændeskiver, og den skal være mindst {d} mm. Hvert trin, med dine egne tal, står på beregningssiden.","Hex bolt M8 × 60":"Sekskantbolt M8 × 60","the pin the thread cone stands on":"tappen, trådkeglen står på","Eyelet and tension bracket":"Beslag til øje og spænding","Above the cone: the eyelet for the thread and the M4 post for the tension discs (tap it M4).":"Over keglen: øjet til tråden og M4-tappen til spændeskiverne (skær M4-gevind).","Tension discs":"Spændeskiver","Cone pin, M8 bolt":"Keglens tap, M8-bolt","Winding tension":"Viklespænding","How hard the thread is pulled as it leaves the guide, set at the disc tensioner. About 0.25 N: the thread should just lift 25 g. The build page shows the working.":"Hvor hårdt tråden trækkes, når den forlader guiden; indstilles på spændeskiverne. Ca. 0,25 N: tråden skal lige akkurat løfte 25 g. Byggesiden viser udregningen.","Winding at {t} N: the longest line needs at least {m} N to lie straight, and the busiest nail ({n} wraps) bends above about {l} N. The thread breaks at about {b} N; the highest tension while winding is about {p} N.":"Vikling ved {t} N: den længste linje skal have mindst {m} N for at ligge lige, og det mest brugte søm ({n} viklinger) bøjer over ca. {l} N. Tråden knækker ved ca. {b} N; den højeste spænding under viklingen er ca. {p} N.","Lower the tension, or use 2 mm nails.":"Sænk spændingen, eller brug søm på 2 mm.","Raise the tension a little.":"Hæv spændingen lidt.","The thread is too thin to be safe: it should hold at least {r} N. Use 0.15 mm polyester or thicker.":"Tråden er for tynd til at være sikker: den bør holde mindst {r} N. Brug polyester på 0,15 mm eller tykkere.","dancer eye":"danserarmens øje","PTFE tube, all its bends":"PTFE-slange, alle dens bøjninger","guide tube tip":"guiderørets spids",polyester:"polyester",nylon:"nylon",cotton:"bomuld","How hard the machine pulls the thread decides two things: whether the busiest nails bend, and how thin the thread may be. Each step below gives its formula with the numbers put in. Friction coefficients, the nails' steel and the threads' strength are typical values, not measurements, so check the real tension once the machine runs.":"Hvor hårdt maskinen trækker i tråden, afgør to ting: om de mest brugte søm bøjer, og hvor tynd tråden må være. Hvert trin nedenfor giver formlen med tallene sat ind. Friktionskoefficienter, sømmenes stål og trådenes styrke er typiske værdier, ikke målinger, så tjek den virkelige spænding, når maskinen kører.","1. Where the tension comes from":"1. Hvor spændingen kommer fra","The thread runs from the cone through the tension discs, the dancer eye, the PTFE tube and the guide tube, then over the tube's tip to the nail. The tension as it leaves the tip is the tension the line keeps on the board:":"Tråden løber fra keglen gennem spændeskiverne, danserarmens øje, PTFE-slangen og guiderøret og så over rørets spids til sømmet. Spændingen, når den forlader spidsen, er den spænding, linjen beholder på pladen:","2. How fast thread is pulled off":"2. Hvor hurtigt tråden trækkes af","While the board turns, the line from the last nail to the guide grows at most as fast as the rim moves. It never shortens: each wrap ends on the side facing the next nail, so the line only lengthens, and the thread never goes slack.":"Mens pladen drejer, vokser linjen fra det sidste søm til guiden højst så hurtigt, som kanten bevæger sig. Den bliver aldrig kortere: hver vikling slutter på den side, der vender mod næste søm, så linjen bliver kun længere, og tråden bliver aldrig slap.","3. Friction along the path":"3. Friktion på vejen","Where the thread bends round something it rubs, and the tension grows by e<sup>μθ</sup> (the capstan equation; θ is the bend in radians, μ the friction coefficient):":"Hvor tråden bøjer rundt om noget, gnider den, og spændingen vokser med e<sup>μθ</sup> (kabestanligningen; θ er bøjningen i radianer, μ friktionskoefficienten):",Point:"Sted","So the tension discs only have to give about a third of the tension wanted on the board.":"Så spændeskiverne skal kun give omkring en tredjedel af den spænding, man vil have på pladen.","4. The spool's inertia":"4. Spolens inerti","A spool that turns on a pin has to be speeded up with the thread. A full one (thread and core {m} g, radius {ro} mm on a {ri} mm core):":"En spole, der drejer på en tap, skal sættes i gang sammen med tråden. En fuld spole (tråd og kerne {m} g, radius {ro} mm på en kerne på {ri} mm):","A cone that stands still only speeds up the thread itself: {t} N, nothing.":"En kegle, der står stille, sætter kun selve tråden i gang: {t} N, ingenting.","5. As the spool empties":"5. Når spolen tømmes","A felt brake on a turning spool gives a fixed torque <i>M</i>, so the tension is <i>T</i> = <i>M</i> / <i>r</i>: from a full spool to the core it grows {x} times. Pulled off the top of a standing cone through tension discs, it hardly changes (about ±{v} %). Either way, the friction is a little stronger at each start than while sliding (about ×{s}).":"En filtbremse på en drejende spole giver et fast moment <i>M</i>, så spændingen er <i>T</i> = <i>M</i> / <i>r</i>: fra fuld spole til kernen vokser den {x} gange. Trukket af over toppen af en stående kegle gennem spændeskiver ændrer den sig næsten ikke (ca. ±{v} %). I begge tilfælde er friktionen lidt større ved hver start end under glidning (ca. ×{s}).","6. Lower limit: straight lines":"6. Nedre grænse: lige linjer","The board lies flat while it is wound, so a line sags under its own weight. The thread ({d} mm, about {x} tex, that is {x} g per km) weighs":"Pladen ligger fladt under viklingen, så en linje synker under sin egen vægt. Tråden ({d} mm, ca. {x} tex, altså {x} g pr. km) vejer","At {t} N the longest line ({l} m) sags {s} mm.":"Ved {t} N synker den længste linje ({l} m) {s} mm.","7. Upper limit: the busiest nail":"7. Øvre grænse: det mest brugte søm","Each wrap pulls the nail with two legs of tension <i>T</i>, both heading into the board. A line to a nail Δ away leaves at (90° − Δ/2) from straight inward; averaged over the lines allowed, the inward share is <i>s</i>, and the sideways shares mostly cancel. The wraps sit {z0} to {z1} mm up, so the pull acts about <i>h</i> above where the nail is held (adding one nail diameter for the wood giving way).":"Hver vikling trækker i sømmet med to stykker tråd med spændingen <i>T</i>, begge ind mod pladen. En linje til et søm Δ væk går ud i (90° − Δ/2) fra lige indad; i gennemsnit over de tilladte linjer er den indadgående andel <i>s</i>, og sideandelene ophæver for det meste hinanden. Viklingerne ligger {z0} til {z1} mm oppe, så trækket virker ca. <i>h</i> over der, hvor sømmet holdes (plus én sømdiameter, fordi træet giver efter).",Nail:"Søm","Steel {s} MPa":"Stål {s} MPa","The wood holds well below that, and the nail bends elastically only a few hundredths of a millimetre: the risk is the steel yielding, which leaves the nail leaning in for good.":"Træet holder langt bedre end det, og sømmet bøjer kun elastisk et par hundrededele millimeter: risikoen er, at stålet giver efter, så sømmet bliver stående skævt indad for altid.","8. The highest tension the thread sees":"8. Den højeste spænding, tråden får","spool on a pin":"spole på en tap","standing cone":"stående kegle","With a spool on a pin the steady tension near its core would be {t} N, above what the nails take: that is why the machine stands the thread on a cone.":"Med en spole på en tap ville den jævne spænding nær kernen være {t} N, mere end sømmene kan tåle: derfor står tråden på en kegle i maskinen.","9. How thin the thread may be":"9. Hvor tynd tråden må være","The thread must hold the highest tension {sf} times over, also at the knot that ties it on (a knot keeps about {k} % of the strength). Its strength per tex and its density give the diameter (fibres fill about {f} % of a twisted thread):":"Tråden skal holde den højeste spænding {sf} gange, også ved knuden, den bindes fast med (en knude bevarer ca. {k} % af styrken). Styrken pr. tex og densiteten giver diameteren (fibrene fylder ca. {f} % af en snoet tråd):","strength per tex":"styrke pr. tex",Strength:"Styrke","Standing cone":"Stående kegle","Spool on a pin":"Spole på en tap","10. What it means":"10. Hvad det betyder","<b>Wind at {a}–{b} N; {t} N is set.</b> The thread leaving the guide should just lift a {g} g weight (or read it on a luggage scale).":"<b>Vikl ved {a}–{b} N; {t} N er indstillet.</b> Tråden, der kommer ud af guiden, skal lige akkurat løfte et lod på {g} g (eller aflæs det på en bagagevægt).","<b>The thread stands on a cone</b> and comes off over its top through tension discs, so the tension stays put as the cone empties.":"<b>Tråden står på en kegle</b> og trækkes af over toppen gennem spændeskiver, så spændingen holder sig, mens keglen tømmes.","<b>Thread at least {d} mm</b>: thinner would hold in theory, but leaves nothing for wear at the tube tip or a weak spot. The app does not go below it. The usual {u} mm polyester holds the peak {s} times over.":"<b>Tråd på mindst {d} mm</b>: tyndere ville holde i teorien, men giver ingen margen for slid ved rørets spids eller et svagt sted. Appen går ikke under det. Den sædvanlige polyester på {u} mm holder toppen {s} gange.","<b>2 mm nails</b> for pieces whose busiest nail gets more than about 25 wraps (the machine page counts them and warns).":"<b>Søm på 2 mm</b> til værker, hvor det mest brugte søm får mere end ca. 25 viklinger (maskinsiden tæller dem og advarer).","<b>The turntable motor</b> feels the thread as {a} N·m extra, {b} N·m at the peak: nothing next to what it has.":"<b>Drejeskivemotoren</b> mærker tråden som {a} N·m ekstra, {b} N·m ved toppen: ingenting i forhold til, hvad den har.","<b>Tie the thread to nail {n}</b>, check it runs freely from the spool through the guide, then press Resume.":"<b>Bind tråden til søm {n}</b>, tjek at den løber frit fra spolen gennem guiden, og tryk så på Fortsæt.","<b>Planned stop after {n} lines.</b> Check the thread and the tension, then press Resume.":"<b>Planlagt stop efter {n} linjer.</b> Tjek tråden og spændingen, og tryk så på Fortsæt.","<b>Finished!</b> Tie the thread off at nail {n}, then press Resume to lift the guide clear.":"<b>Færdig!</b> Bind tråden af ved søm {n}, og tryk så på Fortsæt for at løfte guiden fri.","<b>Paused</b> at about line {n}. Resume, stop, or go back a few lines.":"<b>Sat på pause</b> ved ca. linje {n}. Fortsæt, stop, eller gå et par linjer tilbage.","<b>The machine stopped on its own</b> at about line {n}: the thread may have broken or run out. Mend it and press Resume, or go back a few lines and wind them again.":"<b>Maskinen stoppede af sig selv</b> ved ca. linje {n}: tråden kan være knækket eller sluppet op. Ret det, og tryk på Fortsæt, eller gå et par linjer tilbage og vikl dem igen.",Connected:"Forbundet","Connect the machine":"Forbind maskinen",ready:"klar",running:"kører",holding:"holder",jogging:"flytter manuelt",alarm:"alarm",homing:"referencekører","door open":"dør åben","check mode":"kontroltilstand",asleep:"i dvale","waiting for the controller…":"venter på styringen…","feed {f} %":"fremføring {f} %","Line {k} of {l} · {a} of {t} commands sent":"Linje {k} af {l} · {a} af {t} kommandoer sendt","The controller refused line {l} (error {c}: <code>{t}</code>). The winding is held: resume to skip it, or stop.":"Styringen afviste linje {l} (fejl {c}: <code>{t}</code>). Viklingen holder: fortsæt for at springe den over, eller stop.","Alarm {c}: the controller has stopped and needs unlocking ($X) or homing. If the board turned while stopped, set the zero again.":"Alarm {c}: styringen er stoppet og skal låses op ($X) eller referencekøres. Hvis pladen drejede, mens den var stoppet, så sæt nulpunktet igen.","The winding is finished: {n} lines.":"Viklingen er færdig: {n} linjer.","Stopped; the position is kept. To carry on, unwind the thread back to nail {n} and start from line {k}.":"Stoppet; positionen er bevaret. For at fortsætte skal du vikle tråden tilbage til søm {n} og starte fra linje {k}.","The connection to the controller was lost.":"Forbindelsen til styringen blev afbrudt.","Connected. GRBL answers with a welcome line; press Unlock or Home if it reports an alarm.":"Forbundet. GRBL svarer med en velkomstlinje; tryk på Lås op eller Referencekør, hvis den melder alarm.","Starting at line {k}: the guide rises, goes inside the ring and turns to nail {n}, then stops for the thread.":"Starter ved linje {k}: guiden hæver sig, kører ind i ringen og drejer til søm {n} og stopper så for tråden.","Winding from line {k}.":"Vikler fra linje {k}.","Sending the settings, one at a time.":"Sender indstillingerne, én ad gangen.","Zero set: X0 at nail 0, Y0 on the nail circle, Z at the nail tops.":"Nulpunkt sat: X0 ved søm 0, Y0 på sømcirklen, Z ved sømmenes top.","status shows the work position and buffer use":"status viser arbejdspositionen og bufferforbruget","step pulse, µs":"skridtimpuls, µs","keep the motors powered when idle, so the board cannot drift":"hold motorerne strømførende i hvile, så pladen ikke kan glide","limit switches: normally open":"endestopafbrydere: normalt åbne","no soft limits: the board turns many times":"ingen softwaregrænser: pladen drejer mange gange","no hard limits":"ingen hårde grænser","homing on":"referencekørsel slået til","home X towards −, Y towards +, Z towards +":"reference for X mod −, Y mod +, Z mod +","homing feed, °/min or mm/min":"langsom referencefart, °/min eller mm/min","homing seek, °/min or mm/min":"hurtig referencefart, °/min eller mm/min","pull-off after homing, mm":"tilbagetræk efter reference, mm","X steps per degree of board turn":"X-skridt pr. grads drejning af pladen","Y steps per mm":"Y-skridt pr. mm","Z steps per mm":"Z-skridt pr. mm","X top speed, °/min":"X-topfart, °/min","Y top speed, mm/min":"Y-topfart, mm/min","Z top speed, mm/min":"Z-topfart, mm/min","X acceleration, °/s²":"X-acceleration, °/s²","Y acceleration, mm/s²":"Y-acceleration, mm/s²","Z acceleration, mm/s²":"Z-acceleration, mm/s²","Wood and board":"Træ og plade",Mechanics:"Mekanik",Electronics:"Elektronik","Thread and consumables":"Tråd og forbrugsvarer","Birch plywood 18 mm, for the base":"Birkekrydsfiner 18 mm, til bunden","760 × 940 mm":"760 × 940 mm","Birch plywood 12 mm, for the platter":"Birkekrydsfiner 12 mm, til drejepladen","a 700 mm disc":"en skive på 700 mm","Birch plywood 18 mm, for the nail board":"Birkekrydsfiner 18 mm, til sømpladen","a 640 mm disc, one per piece":"en skive på 640 mm, én pr. værk","Panel pins (brads)":"Dykkere (pladesøm)","1.5 × 30 mm, a pack of 500":"1,5 × 30 mm, pakke med 500","Furniture feet":"Møbelben","75 mm tall, screw-on":"75 mm høje, til at skrue på","Lazy-susan bearing":"Drejeskiveleje (lazy susan)","305 mm (12 in), aluminium, 100 kg or more":"305 mm (12 in), aluminium, 100 kg eller mere","Steel dowel":"Ståldyvel","Ø 10 × 40 mm":"Ø 10 × 40 mm","Aluminium extrusion 2040 (V-slot)":"Aluminiumsprofil 2040 (V-slot)","260 mm, with T-nuts":"260 mm, med T-møtrikker","Screws, nuts and washers":"Skruer, møtrikker og skiver","M3, M4 and M5 assortment; 4 × 16 mm wood screws":"sortiment M3, M4 og M5; træskruer 4 × 16 mm","Stepper motor NEMA 17":"Stepmotor NEMA 17","42 × 48 mm, 0.45 N·m, 1.5 A":"42 × 48 mm, 0,45 N·m, 1,5 A","Stepper motor NEMA 17 with T8 lead screw":"Stepmotor NEMA 17 med T8-spindel","200 mm screw, 8 mm lead, anti-backlash nut":"spindel på 200 mm, stigning 8 mm, slørfri møtrik","GT2 pulley, 20 teeth":"GT2-remskive, 20 tænder","5 mm bore, for 6 mm belt":"5 mm boring, til 6 mm rem","GT2 idler, 20 teeth":"GT2-styrehjul, 20 tænder","5 mm bore":"5 mm boring","GT2 closed belt":"Lukket GT2-rem","400 mm, 6 mm wide":"400 mm, 6 mm bred","GT2 open belt":"Åben GT2-rem","6 mm wide, 0.5 m":"6 mm bred, 0,5 m","Linear rail MGN12H":"Lineærskinne MGN12H","200 mm, one carriage":"200 mm, én slæde","Linear rail MGN9H":"Lineærskinne MGN9H","120 mm, one carriage":"120 mm, én slæde","Arduino Uno (or compatible)":"Arduino Uno (eller kompatibel)","with GRBL 1.1 flashed":"med GRBL 1.1 indlæst","CNC Shield V3":"CNC Shield V3","for the Uno":"til Uno'en","Stepper driver TMC2209":"Stepmotordriver TMC2209","standalone (step/dir) module":"selvstændigt modul (step/dir)","Power supply 12 V 5 A":"Strømforsyning 12 V 5 A","with a switch or switched cable":"med afbryder eller kabel med afbryder","Microswitch with lever":"Mikroafbryder med arm","Y and Z home, thread break":"Y- og Z-reference, trådbrud","Hall sensor A3144 and a magnet":"Hall-sensor A3144 og en magnet","magnet Ø 6 × 3 mm, for homing the turntable":"magnet Ø 6 × 3 mm, til drejeskivens referencepunkt","Wire, connectors and a project box":"Ledninger, stik og en kasse","4-wire motor cables, Dupont leads":"4-leder motorkabler, Dupont-ledninger","Brass tube":"Messingrør","2.5 mm outside, 1.6 mm inside, cut to 40 mm":"2,5 mm udvendig, 1,6 mm indvendig, skåret til 40 mm","PTFE tube":"PTFE-slange","4 × 2 mm, 0.5 m":"4 × 2 mm, 0,5 m","Thread tension discs":"Trådspændeskiver","two Ø 16 mm discs, a spring and a wing nut on an M4 bolt, as on a sewing machine":"to skiver Ø 16 mm, en fjeder og en vingemøtrik på en M4-bolt, som på en symaskine","Black polyester thread on a cone":"Sort polyestertråd på kegle","0.15 to 0.3 mm (0.25 mm usual), 3,000 m or more per piece":"0,15 til 0,3 mm (normalt 0,25 mm), 3.000 m eller mere pr. værk","Filament PETG":"Filament PETG","about 0.5 kg for all printed parts":"ca. 0,5 kg til alle printede dele","Turntable pulley, 160 teeth":"Drejeskivens remskive, 160 tænder","PETG, 0.1 mm layers for the teeth, 4 walls, 40 % infill. Hub down.":"PETG, lag på 0,1 mm til tænderne, 4 vægge, 40 % fyld. Navet nedad.","Turntable motor plate":"Motorplade til drejeskiven","Under the base; the slots tension the belt.":"Under bunden; slidserne strammer remmen.","Turn button":"Drejelås","Three hold the nail board on the platter.":"Tre holder sømpladen fast på drejepladen.","Hall sensor holder":"Holder til Hall-sensor","On the base, under the magnet's path.":"På bunden, under magnetens bane.","Tower foot, left":"Tårnfod, venstre","Holds the extrusion upright.":"Holder profilen lodret.","Tower foot, right":"Tårnfod, højre","Height motor mount":"Beslag til højdemotor","On top of the extrusion.":"Øverst på profilen.","Height carriage with shelf":"Højdeslæde med hylde","PETG, 5 walls, 40 % infill. Shelf down; the gussets need no support.":"PETG, 5 vægge, 40 % fyld. Hylden nedad; knægtene kræver ingen støtte.","Guide arm":"Guidearm","Press the brass tube in from below; the PTFE tube pushes into the socket on top.":"Pres messingrøret ind nedefra; PTFE-slangen skubbes ind i holderen ovenpå.","Cone stand":"Keglestativ","The thread cone stands on it, on an M8 bolt; the thread comes off over the top.":"Trådkeglen står på det, på en M8-bolt; tråden trækkes af over toppen.","Dancer bracket":"Beslag til danserarm","Carries the dancer's pivot and the thread-break switch.":"Bærer danserarmens drejetap og trådbrudsafbryderen.","Dancer arm":"Danserarm","Rides on the thread; if the thread breaks it drops onto the switch.":"Hviler på tråden; knækker tråden, falder den ned på afbryderen.","Base, 18 mm plywood":"Bund, 18 mm krydsfiner","Platter, 12 mm plywood":"Drejeplade, 12 mm krydsfiner","Nail board":"Sømplade","Centre dowel":"Centerdyvel","Homing magnet":"Referencemagnet","Tower, 2040 extrusion":"Tårn, 2040-profil","Height rail, MGN12":"Højdeskinne, MGN12","Height rail carriage":"Slæde på højdeskinnen","Guide rail, MGN9":"Guideskinne, MGN9","Guide rail carriage":"Slæde på guideskinnen","Height motor with lead screw":"Højdemotor med spindel","Guide motor":"Guidemotor","Turntable motor":"Drejeskivemotor","Guide belt pulley":"Remskive til guiderem","Guide belt idler":"Styrehjul til guiderem","Guide belt":"Guiderem","Motor pulley, 20 teeth":"Motorremskive, 20 tænder","Turntable belt":"Drejeskiverem","Brass guide tube":"Guiderør af messing","PTFE tube for the thread":"PTFE-slange til tråden","Thread cone":"Trådkegle","Thread-break switch":"Trådbrudsafbryder","Controller: Arduino Uno with CNC Shield":"Styring: Arduino Uno med CNC Shield","Power supply":"Strømforsyning",Foot:"Ben","<b>Print</b> the parts below. PETG is best for the pulley and the carriage, which carry load; PLA will do for the rest.":"<b>Print</b> delene nedenfor. PETG er bedst til remskiven og slæden, som bærer belastning; PLA er fint til resten.","<b>Base.</b> Cut the board to size and cut the opening for the pulleys and the belt. Drill the holes from the drilling plan and screw on the feet.":"<b>Bund.</b> Skær pladen til og skær åbningen til remskiverne og remmen. Bor hullerne efter boreplanen, og skru benene på.","<b>Bearing.</b> Centre the bearing on the opening and screw its lower plate to the base. Drill the 20 mm access hole where one of the upper plate's holes falls.":"<b>Leje.</b> Centrér lejet over åbningen, og skru dets nederste plade fast på bunden. Bor det 20 mm adgangshul, hvor et af den øverste plades huller falder.","<b>Platter.</b> Cut the 700 mm disc and drill the 10 mm centre hole and the magnet hole underneath. Screw the turntable pulley to its underside, with the dowel through both, then glue the magnet in.":"<b>Drejeplade.</b> Skær skiven på 700 mm, og bor centerhullet på 10 mm og magnethullet på undersiden. Skru drejeskivens remskive fast på undersiden med dyvlen gennem begge, og lim så magneten i.","<b>Turntable.</b> Set the platter on the bearing and screw it on through the access hole, turning it to reach each screw.":"<b>Drejeskive.</b> Sæt drejepladen på lejet, og skru den fast gennem adgangshullet; drej den for at nå hver skrue.","<b>Turntable drive.</b> Fix the motor to its plate, put the 20-tooth pulley on so its teeth line up with the big pulley, fit the belt and slide the plate outward until the belt is firm but not tight; then screw the plate down.":"<b>Drejeskivens træk.</b> Fastgør motoren til pladen, sæt remskiven med 20 tænder på, så tænderne flugter med den store remskive, læg remmen på, og skub pladen udad, til remmen er fast, men ikke stram; skru så pladen fast.","<b>Homing sensor.</b> Screw the hall sensor holder under the magnet's path, the sensor's flat face up, 1 to 2 mm below the magnet.":"<b>Referencesensor.</b> Skru holderen til Hall-sensoren fast under magnetens bane, med sensorens flade side opad, 1 til 2 mm under magneten.","<b>Tower.</b> Bolt the extrusion upright with the two feet, fit the MGN12 rail on its front face and the height motor on top.":"<b>Tårn.</b> Bolt profilen lodret fast med de to fødder, montér MGN12-skinnen på forsiden og højdemotoren øverst.","<b>Carriage.</b> Bolt the height carriage to the rail carriage and the lead-screw nut to its tab. Fit the MGN9 rail under the shelf, the guide motor and its pulley on the shelf, and the idler at the front.":"<b>Slæde.</b> Bolt højdeslæden fast på skinneslæden og spindelmøtrikken på dens flig. Montér MGN9-skinnen under hylden, guidemotoren og dens remskive på hylden og styrehjulet forrest.","<b>Guide.</b> Deburr and round both ends of the brass tube, press it into the guide arm, and bolt the arm under the MGN9 carriage. Loop the belt round the pulley and the idler and clamp both ends in the arm.":"<b>Guide.</b> Afgrat og afrund begge ender af messingrøret, pres det ind i guidearmen, og bolt armen fast under MGN9-slæden. Læg remmen rundt om remskiven og styrehjulet, og klem begge ender fast i armen.","<b>Thread path.</b> Fit the cone stand with its M8 bolt and the eyelet bracket above it, with the tension discs on their post. Fit the dancer bracket with the arm and the switch so the switch closes when the arm drops, and run the PTFE tube from the dancer to the guide arm. The thread goes up from the cone through the eyelet, between the discs, through the dancer eye and the tube.":"<b>Trådens vej.</b> Montér keglestativet med M8-bolten og øjebeslaget over det med spændeskiverne på deres tap. Montér beslaget til danserarmen med armen og afbryderen, så afbryderen slutter, når armen falder, og før PTFE-slangen fra danserarmen til guidearmen. Tråden går op fra keglen gennem øjet, mellem skiverne, gennem danserarmens øje og slangen.","<b>Switches and wiring.</b> Fit the home switches where the guide and the carriage reach them at the back and the top, then wire everything as in the diagram.":"<b>Afbrydere og ledninger.</b> Montér referenceafbryderne, hvor guiden og slæden når dem bagerst og øverst, og forbind så det hele som på diagrammet.","<b>Flash GRBL 1.1</b> on the Uno and send the settings below, one line at a time, from any G-code sender.":"<b>Indlæs GRBL 1.1</b> på Uno'en, og send indstillingerne nedenfor, én linje ad gangen, fra et hvilket som helst G-kode-program.","<b>Directions.</b> Jog each axis a little. X+ must turn the board anticlockwise seen from the front, Y+ move the guide towards the tower, Z+ raise it. Reverse an axis with $3 if it goes the wrong way.":"<b>Retninger.</b> Kør hver akse lidt. X+ skal dreje pladen mod uret set forfra, Y+ flytte guiden mod tårnet og Z+ hæve den. Vend en akse med $3, hvis den kører den forkerte vej.","<b>Steps.</b> Mark the platter's edge and send G91 G1 X360 F600: the board must turn exactly once. Check Y and Z against a ruler.":"<b>Skridt.</b> Afmærk drejepladens kant, og send G91 G1 X360 F600: pladen skal dreje præcis én omgang. Tjek Y og Z med en lineal.","<b>Homing.</b> Send $H. The guide rises, moves back to its switch, and the board turns until the magnet passes the sensor.":"<b>Reference.</b> Send $H. Guiden hæver sig, kører tilbage til sin afbryder, og pladen drejer, til magneten passerer sensoren.","<b>Work zero.</b> Clamp a board on, jog the guide's tip exactly above nail 0, just clear of its top, and send G10 L20 P1 X0 Y0 Z18 (18 = the nail height). GRBL remembers it.":"<b>Arbejdsnulpunkt.</b> Spænd en plade fast, kør guidens spids præcis over søm 0, lige fri af toppen, og send G10 L20 P1 X0 Y0 Z18 (18 = sømhøjden). GRBL husker det.","<b>Dry run.</b> Without thread, run the demo pattern's G-code at half speed (feed override 50 %). Watch the tube pass through the gaps and round the nails.":"<b>Tørkørsel.</b> Kør demomønstrets G-kode uden tråd ved halv hastighed (fremføring 50 %). Se røret passere gennem mellemrummene og rundt om sømmene.","<b>Tension.</b> Tie the thread on and turn the tension discs' wing nut until the thread leaving the guide just lifts a 25 g weight (0.25 N; see Thread tension above). Then wind your first piece.":"<b>Spænding.</b> Bind tråden fast, og drej spændeskivernes vingemøtrik, til tråden, der kommer ud af guiden, lige akkurat løfter et lod på 25 g (0,25 N; se Trådspænding ovenfor). Vikl så dit første værk.","cut right through":"skær helt igennem","bearing, 305 mm":"leje, 305 mm","Ø 20 access hole: mark through the bearing":"Ø 20 adgangshul: afmærk gennem lejet","motor plate, underneath":"motorplade, på undersiden","hall sensor holder":"holder til Hall-sensor",tower:"tårn",controller:"styring","power supply":"strømforsyning","turntable axis":"drejeskivens akse","Base, 18 mm plywood, seen from above. All sizes in mm; holes Ø 4.5 unless marked.":"Bund, 18 mm krydsfiner, set ovenfra. Alle mål i mm; huller Ø 4,5, medmindre andet er angivet.","Drilling plan for the base":"Boreplan for bunden","nail board, Ø 640":"sømplade, Ø 640","Ø 10 through, for the dowel":"Ø 10 gennemgående, til dyvlen","turn buttons":"drejelåse","pulley, underneath":"remskive, på undersiden","magnet underneath: Ø 6, 3 deep":"magnet på undersiden: Ø 6, 3 dyb","Platter, 12 mm plywood, seen from above; dashed holes are drilled from underneath. Turn buttons every 120°, pulley screws every 60°.":"Drejeplade, 12 mm krydsfiner, set ovenfra; stiplede huller bores fra undersiden. Drejelåse for hver 120°, remskiveskruer for hver 60°.","Drilling plan for the platter":"Boreplan for drejepladen","Arduino Uno + CNC Shield V3":"Arduino Uno + CNC Shield V3","X driver":"X-driver","Y driver":"Y-driver","Z driver":"Z-driver","jumpers M0 + M1: 1/16 step":"jumpere M0 + M1: 1/16 skridt","driver current about 0.8 A":"driverstrøm ca. 0,8 A","Height motor":"Højdemotor","NEMA 17 + T8":"NEMA 17 + T8","Hall sensor A3144":"Hall-sensor A3144","5 V, GND, signal":"5 V, GND, signal","Y home switch":"Y-referenceafbryder","normally open, to GND":"normalt åben, til GND","Z home switch":"Z-referenceafbryder","closes when the dancer drops":"slutter, når danserarmen falder","Resume button (optional)":"Genoptag-knap (valgfri)","to the shield's screw terminal":"til shieldets skrueterminal",Computer:"Computer","USB: G-code sender":"USB: G-kode-program","GRBL 1.1 moves the Z limit to D12, the pin marked SpnEn on the CNC Shield V3; the Z+/Z− header does not work for it.":"GRBL 1.1 flytter Z-grænsen til D12, benet mærket SpnEn på CNC Shield V3; Z+/Z−-stikket virker ikke til den.","Wiring diagram":"Ledningsdiagram","€ {v}":"{v} €","Turntable drive":"Drejeskivens træk","{a} to {b} teeth: {r} : 1":"{a} til {b} tænder: {r} : 1","Motor to turntable axis":"Fra motor til drejeskivens akse","{c} mm, with a {l} mm belt; {m} teeth in mesh":"{c} mm med en rem på {l} mm; {m} tænder i indgreb",Steps:"Skridt","X {x} per degree · Y {y} per mm · Z {z} per mm":"X {x} pr. grad · Y {y} pr. mm · Z {z} pr. mm","Smallest move of a nail":"Et søms mindste bevægelse","{u} µm per microstep":"{u} µm pr. mikroskridt","Motor speeds at top speed":"Motorhastigheder ved topfart","X {x} rpm · Y {y} rpm · Z {z} rpm":"X {x} o/min · Y {y} o/min · Z {z} o/min","Step pulses at top speed":"Skridtimpulser ved topfart","{r} per second at most (GRBL on an Uno manages about {g})":"højst {r} pr. sekund (GRBL på en Uno klarer ca. {g})","Turning load":"Drejende last","{m} kg of platter and board, {i} kg·m²":"{m} kg drejeplade og sømplade, {i} kg·m²","Torque at the motor":"Moment ved motoren","needs {n} N·m to accelerate, has about {a} N·m: {s} times the need":"kræver {n} N·m for at accelerere og har ca. {a} N·m: {s} gange behovet","Under the base":"Under bunden","the motor hangs {h} mm down; the {f} mm feet leave {c} mm to the floor":"motoren hænger {h} mm ned; benene på {f} mm giver {c} mm til gulvet",Part:"Del","Size or type":"Størrelse eller type",Qty:"Antal",About:"Ca.","Total, roughly":"I alt, cirka","{g} g":"{g} g","Size, mm":"Mål, mm",Filament:"Filament","All printed parts":"Alle printede dele","The list of printed parts could not be loaded.":"Listen over printede dele kunne ikke indlæses.",Copied:"Kopieret",wood:"træ",printed:"printet","bought metal parts":"købte metaldele",motors:"motorer",electronics:"elektronik","thread path":"trådens vej","Click a part to see what it is. Drag to turn, scroll to zoom.":"Klik på en del for at se, hvad den er. Træk for at dreje, rul for at zoome.","Loading the 3D model… {p} %":"Indlæser 3D-modellen… {p} %","The 3D model could not be shown in this browser.":"3D-modellen kunne ikke vises i denne browser.",Board:"Plade","Nail diameter":"Sømdiameter","Thicker nails leave a narrower gap for the guide.":"Tykkere søm efterlader et smallere mellemrum til guiden.","Nail height above the board":"Sømhøjde over pladen","The wraps stack up the nails; taller nails hold more.":"Viklingerne stables op ad sømmene; højere søm kan rumme flere.","Thread guide":"Trådguide","Guide tube diameter":"Guiderørets diameter","The outside diameter of the tube tip that passes between the nails.":"Den udvendige diameter af rørspidsen, der passerer mellem sømmene.","Waits inside the ring by":"Venter inden for ringen med","How far inside the nail circle the guide waits while the board turns.":"Hvor langt inden for sømcirklen guiden venter, mens pladen drejer.","Goes outside the ring by":"Går uden for ringen med","How far outside the nail circle the guide goes to wrap a nail.":"Hvor langt uden for sømcirklen guiden går for at vikle om et søm.","First wrap height":"Højde for første vikling","The height of the first wrap on each nail, above the board.":"Højden af den første vikling på hvert søm over pladen.","Rise per wrap":"Stigning pr. vikling","Each later wrap on the same nail is laid this much higher. About the thread diameter.":"Hver senere vikling på samme søm lægges så meget højere. Omtrent trådens diameter.",Motion:"Bevægelse","Board turning speed":"Pladens drejehastighed","Top turning speed of the turntable.":"Drejeskivens højeste drejehastighed.","Board acceleration":"Pladens acceleration","A heavy board needs a gentle acceleration, or the motor skips steps.":"En tung plade kræver en blid acceleration, ellers springer motoren skridt over.","Guide speed":"Guidens hastighed","Top speed of the guide moving in and out.":"Guidens højeste hastighed ind og ud.","Guide acceleration":"Guidens acceleration","Acceleration of the guide moving in and out.":"Guidens acceleration ind og ud.","Height speed":"Højdehastighed","Top speed of the guide moving up and down.":"Guidens højeste hastighed op og ned.","Height acceleration":"Højdeacceleration","Acceleration of the guide moving up and down.":"Guidens acceleration op og ned.","Thread speed":"Trådhastighed","The fastest the thread may be pulled off the spool. It limits how fast the board may turn.":"Det hurtigste, tråden må trækkes af spolen. Det begrænser, hvor hurtigt pladen må dreje.",Controller:"Styring","Steps per degree (turn)":"Skridt pr. grad (drejning)","Motor steps for one degree of board turn: 200 steps × microsteps × gear ratio ÷ 360.":"Motorskridt for én grads drejning af pladen: 200 skridt × mikroskridt × udveksling ÷ 360.","Steps per mm (guide)":"Skridt pr. mm (guide)","Motor steps for one millimetre of guide travel.":"Motorskridt for én millimeters bevægelse af guiden.","Steps per mm (height)":"Skridt pr. mm (højde)","Motor steps for one millimetre of guide height.":"Motorskridt for én millimeters højde af guiden.","Stop every":"Stop for hver",lines:"linjer","The machine stops after this many lines so you can check the thread. 0 never stops.":"Maskinen stopper efter så mange linjer, så du kan tjekke tråden. 0 stopper aldrig.","Demo pattern: a star of 720 lines":"Demomønster: en stjerne med 720 linjer","{name} · {n} nails · {d} mm board · {t} mm thread · {l} lines":"{name} · {n} søm · {d} mm plade · {t} mm tråd · {l} linjer","{h} h {m} min":"{h} t {m} min","{m} min":"{m} min","The guide tube ({g} mm) passes between nails with a {gap} mm gap, leaving {s} mm on each side.":"Guiderøret ({g} mm) passerer mellem søm med et mellemrum på {gap} mm og har {s} mm til hver side.","That is too tight to pass reliably: use a thinner tube or thinner nails, fewer nails or a bigger board.":"Det er for stramt til at passere sikkert: brug et tyndere rør eller tyndere søm, færre søm eller en større plade.","While the board turns, the guide waits {h} mm inside the nail circle, clear of the nails.":"Mens pladen drejer, venter guiden {h} mm inden for sømcirklen, fri af sømmene.","The guide waits only {h} mm inside the nail circle and would hit the nails as the board turns: it needs at least {n} mm.":"Guiden venter kun {h} mm inden for sømcirklen og ville ramme sømmene, når pladen drejer: den skal have mindst {n} mm.","To wrap a nail the guide goes {h} mm outside the nail circle, clear of the nails.":"For at vikle om et søm går guiden {h} mm uden for sømcirklen, fri af sømmene.","The guide goes only {h} mm outside the nail circle and would hit the nail it wraps: it needs at least {n} mm.":"Guiden går kun {h} mm uden for sømcirklen og ville ramme det søm, den vikler om: den skal have mindst {n} mm.","The first wrap height is not below the top limit, 2 mm under the nail tops ({t} mm). Lower it or use taller nails.":"Højden for første vikling ligger ikke under den øvre grænse, 2 mm under sømmenes top ({t} mm). Sænk den, eller brug højere søm.","The busiest nail gets {w} wraps; the highest is laid {z} mm above the board, below the {t} mm limit.":"Det mest brugte søm får {w} viklinger; den højeste lægges {z} mm over pladen, under grænsen på {t} mm.","{c} wraps would go higher and are laid at the limit, pressed onto earlier ones. Use taller nails or a smaller rise per wrap.":"{c} viklinger ville komme højere og lægges ved grænsen, presset ned på tidligere viklinger. Brug højere søm eller en mindre stigning pr. vikling.","No line rubs a neighbouring nail: the closest passes {w} mm clear.":"Ingen linje gnider mod et nabosøm: den nærmeste går {w} mm fri.","{n} of {l} lines leave a nail at a shallow angle and rub the next nail, which pulls them slightly out of line (by up to {w} mm). Lines that skip at least {s} nails are clear; this piece's smallest skip is {m}. To avoid it, set the minimum nail skip in the app to {s}.":"{n} af {l} linjer forlader et søm i en flad vinkel og gnider mod det næste søm, så de trækkes lidt ud af kurs (op til {w} mm). Linjer, der springer mindst {s} søm over, går fri; dette værks mindste spring er {m}. Sæt mindste sømspring i appen til {s} for at undgå det.","The board turns at {v} °/s at most: any faster and the rim would pull thread off the spool faster than {t} mm/s.":"Pladen drejer højst {v} °/s: hurtigere ville kanten trække tråd af spolen hurtigere end {t} mm/s.","The board turns at up to {v} °/s.":"Pladen drejer op til {v} °/s.","Winding time (estimate, without stops)":"Viklingstid (skøn, uden stop)","Per line, on average":"Pr. linje i gennemsnit","Machine moves":"Maskinbevægelser","The board turns in all":"Pladen drejer i alt","{n} turns":"{n} omgange","Wraps on the busiest nail":"Viklinger på det mest brugte søm","{m} m between nails, plus about {w} m round the nails":"{m} m mellem sømmene plus ca. {w} m rundt om sømmene","setting up":"gør klar","turning to the nail":"drejer hen til sømmet","setting the height":"indstiller højden","guide out":"guide ud",wrapping:"vikler","guide in":"guide ind",finished:"færdig","Line {k} of {l}":"Linje {k} af {l}","nail {a} → {b}":"søm {a} → {b}",Play:"Afspil","Your last result ({src})":"Dit seneste resultat ({src})","Your last result":"Dit seneste resultat","No result from the app in this browser yet, so here is a demo pattern. Make a piece in the app, or open a project file.":"Der er endnu intet resultat fra appen i denne browser, så her er et demomønster. Lav et værk i appen, eller åbn en projektfil.","Finished.":"Færdig.","Line {n} of {t}":"Linje {n} af {t}","Done! Tie the thread off at nail {n}.":"Færdig! Bind tråden af ved søm {n}.","from nail {n}":"fra søm {n}","Portrait – fine":"Portræt – fint","Portrait – bold":"Portræt – kraftigt","High-contrast graphic":"Grafik med høj kontrast","300 nails, 0.2 mm thread, up to 4,500 lines: fine detail and soft tones. Takes longest to wind.":"300 søm, 0,2 mm tråd, op til 4.500 linjer: fine detaljer og bløde toner. Tager længst tid at vikle.","200 nails, 0.4 mm thread, up to 2,500 lines: strong shapes that read from across a room.":"200 søm, 0,4 mm tråd, op til 2.500 linjer: kraftige former, der kan ses på tværs af et rum.","240 nails, dark thread and a length penalty: solid areas fill and edges near the rim stay crisp. For logos and silhouettes.":"240 søm, mørk tråd og længdestraf: ensfarvede områder fyldes ud, og kanter nær randen forbliver skarpe. Til logoer og silhuetter.","Preset “{name}”: {tip}":"Forvalg “{name}”: {tip}","Your last result is shown again ({n} lines{src}). Load a picture to make a new one.":"Dit seneste resultat vises igen ({n} linjer{src}). Indlæs et billede for at lave et nyt.","Project loaded: the solver reproduced the saved sequence exactly ({n} lines).":"Projekt indlæst: beregningen gentog den gemte rækkefølge præcist ({n} linjer).","Project loaded, but this run differs from the saved sequence. It was probably saved with another version of the app.":"Projekt indlæst, men denne beregning afviger fra den gemte rækkefølge. Det er nok gemt med en anden version af appen.","That project file is damaged: its picture does not match its fingerprint.":"Projektfilen er beskadiget: billedet passer ikke til dets fingeraftryk.","That project was saved by a newer version of the app.":"Projektet er gemt med en nyere version af appen.","That is not a String Art project file.":"Det er ikke en String Art-projektfil.","String Art nail template · {n} nails · {d} mm board":"String Art-sømskabelon · {n} søm · plade på {d} mm","100 mm × 100 mm: check with a ruler":"100 mm × 100 mm: kontrollér med en lineal","row {r}, column {c}":"række {r}, kolonne {c}","{n} pages of {paper} for a {d} mm board.":"{n} sider i {paper} til en plade på {d} mm.","Print these pages at actual size (100 %, no scaling), check the 100 mm square with a ruler, then trim and tape the pages together, matching the crosses in the shaded overlaps.":"Udskriv siderne i faktisk størrelse (100 %, ingen skalering), kontrollér kvadratet på 100 mm med en lineal, og klip og tape så siderne sammen, så krydsene i de skraverede overlap passer.","Sample portrait":"Eksempelportræt","The sample could not be loaded.":"Eksemplet kunne ikke indlæses.","{n}, numbered 0 to {m} clockwise; nail 0 at the top":"{n}, nummereret 0 til {m} med uret; søm 0 øverst","{d} mm (the circle the nails stand on)":"{d} mm (cirklen, sømmene står på)","{t} mm black; you need {m} m, plus {s} m for wrapping and slack":"{t} mm sort; du skal bruge {m} m plus {s} m til omvikling og slæk",Start:"Start","tie the thread to nail {n}":"bind tråden til søm {n}","String Art — winding instructions":"String Art — viklevejledning","Made with String Art version {v} on {d}.":"Lavet med String Art version {v} den {d}.","The finished piece, as simulated":"Det færdige værk, simuleret","How to wind":"Sådan vikler du","Number the nails 0 to {m} clockwise, starting with nail 0 at the top (12 o'clock).":"Nummerér sømmene 0 til {m} med uret, med søm 0 øverst (klokken 12).","Tie the thread to nail {n}.":"Bind tråden til søm {n}.","Read each block left to right: take the thread straight across the board to the next nail, once around it, and on to the next. Keep the thread taut.":"Læs hver blok fra venstre mod højre: før tråden lige over pladen til det næste søm, én gang rundt om det og videre til det næste. Hold tråden stram.","Tick a block when it is done. The ticks are remembered in this browser, so you can stop and carry on later.":"Sæt flueben ved en blok, når den er færdig. Fluebenene huskes i denne browser, så du kan holde pause og fortsætte senere.","After the last nail, tie the thread off.":"Bind tråden af efter det sidste søm.","Print or save as PDF":"Udskriv eller gem som PDF","{n} of {t} blocks done":"{n} af {t} blokke færdige","Low contrast (spread {s}). String art draws with the differences between areas: with little contrast every line darkens everything about equally and the result is a grey haze. Raise the contrast, try the local contrast boost, or choose a picture with stronger lights and darks.":"Lav kontrast (spredning {s}). Trådkunst tegner med forskellene mellem områder: med lidt kontrast gør hver linje alt næsten lige mørkt, og resultatet bliver en grå dis. Skru op for kontrasten, prøv den lokale kontrastforstærkning, eller vælg et billede med kraftigere lys og skygge.","Busy border. Every line starts and ends at the rim, so detail or texture near the edge turns into clutter that crosses the whole picture. Zoom in on the subject or choose a plainer background.":"Uroligt kantområde. Hver linje starter og slutter ved kanten, så detaljer eller tekstur nær kanten bliver til rod, der krydser hele billedet. Zoom ind på motivet, eller vælg en mere ensfarvet baggrund.","Good contrast and a quiet border: this picture should work well.":"God kontrast og en rolig kant: dette billede burde fungere godt.","{d}°":"{d}°","{p} % of the board":"{p} % af pladen","String Art version {v}":"String Art version {v}","That file could not be read. Use a JPG, PNG or WebP picture.":"Filen kunne ikke læses. Brug et JPG-, PNG- eller WebP-billede.","The solver stopped with an error.":"Beregningen stoppede med en fejl.","Preparing the lines…":"Forbereder linjerne …","Line {n} of {k} · RMSE {e}":"Linje {n} af {k} · RMSE {e}","Paused.":"Sat på pause.","The solver stopped with an error: {e}":"Beregningen stoppede med en fejl: {e}","Done: {n} lines, the most allowed.":"Færdig: {n} linjer, det højest tilladte.","Done: {n} lines. More lines would not improve the picture.":"Færdig: {n} linjer. Flere linjer ville ikke gøre billedet bedre.","Done: {n} lines. Every allowed line from the last nail has been used.":"Færdig: {n} linjer. Alle tilladte linjer fra det sidste søm er brugt.","Stopped after {n} lines.":"Stoppet efter {n} linjer.","Pausing…":"Sætter på pause …",Resume:"Fortsæt",Pause:"Pause",Lines:"Linjer","RMSE (lower is better)":"RMSE (lavere er bedre)","SSIM, pixel by pixel":"SSIM, pixel for pixel","SSIM, seen from a distance":"SSIM, set på afstand",Thread:"Tråd","{m} m, plus {s} m for wrapping and slack":"{m} m plus {s} m til omvikling og slæk",Time:"Tid","{s} s":"{s} s","Line cache":"Linjecache","all lines precomputed, {mb} MB":"alle linjer beregnet på forhånd, {mb} MB","lines computed as needed":"linjer beregnes efter behov","Board diameter":"Pladens diameter","Diameter of the nail circle on the real board. A bigger board shows finer detail and uses more thread.":"Diameteren af sømcirklen på den rigtige plade. En større plade viser finere detaljer og bruger mere tråd.",Nails:"Søm","How many nails around the circle. More nails give finer detail but take longer to wind.":"Hvor mange søm der sidder rundt om cirklen. Flere søm giver finere detaljer, men tager længere tid at vikle.","Thread diameter":"Trådens tykkelse","Thicker thread darkens faster: each line covers more of the board. At least 0.15 mm, so the winding machine cannot break it.":"Tykkere tråd gør mørkere hurtigere: hver linje dækker mere af pladen. Mindst 0,15 mm, så viklemaskinen ikke kan knække den.","Most lines":"Højst antal linjer","The most lines to wind. The solver stops earlier if no line improves the picture any more.":"Det højeste antal linjer, der vikles. Beregningen stopper før, hvis ingen linje gør billedet bedre længere.","Minimum nail skip":"Mindste sømspring","No line may join nails closer than this. Short lines near the rim only add clutter.":"Ingen linje må forbinde søm, der sidder tættere end dette. Korte linjer ved kanten giver kun rod.","Uses per line":"Brug pr. linje","How many times the thread may join the same two nails.":"Hvor mange gange tråden må forbinde de samme to søm.","Start nail":"Startsøm","The nail where the thread is tied on. Nail 0 is at the top; numbers run clockwise.":"Sømmet, hvor tråden bindes fast. Søm 0 sidder øverst; numrene løber med uret.","Working resolution":"Arbejdsopløsning","Size of the picture the solver compares against, in pixels. Higher is more precise but slower and uses more memory.":"Størrelsen på billedet, beregningen sammenligner med, i pixel. Højere er mere præcist, men langsommere og bruger mere hukommelse.","Darkness factor":"Mørkefaktor","How dark one pass of thread counts. Above 1 the solver reaches the same darkness with fewer lines; below 1 it uses more.":"Hvor mørk én gang tråd regnes for. Over 1 når beregningen samme mørke med færre linjer; under 1 bruger den flere.","Length penalty β":"Længdestraf β","Above 0, long lines count for less: a line's score is divided by its length to this power. It brings out detail near the edge.":"Over 0 tæller lange linjer mindre: en linjes point divideres med dens længde opløftet til denne potens. Det fremhæver detaljer nær kanten.","Stop threshold ε":"Stopgrænse ε","Stop once the best line improves the picture by less than this for 20 lines in a row. 0 stops when lines stop helping.":"Stop, når den bedste linje forbedrer billedet med mindre end dette 20 linjer i træk. Med 0 stopper den, når linjerne holder op med at hjælpe.","What does this do?":"Hvad gør denne?"},H:{"calc.title":"String Art — Beregninger","calc.meta":"Hvor hårdt viklemaskinen trækker i tråden, hvad der begrænser det, og hvor tynd tråden må være: hvert trin med formlen og tallene sat ind, for din egen maskine og dit eget værk.","calc.sub":"beregninger","calc.h1":"Beregninger: trådspænding","calc.intro":"Hvor hårdt viklemaskinen trækker i tråden, afgør, om de mest brugte søm bøjer, og hvor tynd tråden må være. Skift tallene nedenfor ud med din egen maskines og dit eget værks: hvert trin regnes om.","calc.h.inputs":"Dine tal","calc.reset":"Maskinens standardværdier","bd.calcLink":"Alle beregningerne","nav.calc":"Beregninger","bd.h.tension":"Trådspænding","wd.h":"Vikl det med din maskine","wd.noSerial":"For at styre maskinen skal du bruge Chrome eller Edge på en computer: de kan tale med styringen via USB. Du kan stadig hente G-koden og sende den med et hvilket som helst G-kode-program.","wd.connect":"Forbind maskinen","wd.h.setup":"Klargør","wd.home":"Referencekør","wd.unlock":"Lås op","wd.settings":"Send indstillingerne","wd.prevNail":"◀ ét søm","wd.nextNail":"ét søm ▶","wd.in":"◀ ind","wd.out":"ud ▶","wd.down":"▼ ned","wd.up":"op ▲","wd.zero":"Guiden er over søm 0: sæt nulpunkt","wd.h.wind":"Vikl","wd.from":"Fra linje","wd.start":"Start","wd.pause":"Pause","wd.resume":"Fortsæt","wd.stop":"Stop","wd.back":"Gå tilbage","wd.lines":"linjer","wd.backBtn":"Gå tilbage","wd.speed":"Hastighed","wd.console":"Styringens konsol","wd.send":"Send","wd.disconnect":"Afbryd forbindelsen","wd.jog":"Flyt manuelt","wd.step":"Flyttetrin","wd.cmdHint":"En G-kode- eller $-kommando","bd.title":"String Art — Byg viklemaskinen","bd.meta":"Byg String Arts viklemaskine: en 3D-model, delene der skal købes, dele til 3D-print, boreplaner, ledningsdiagram, styringens indstillinger og samling trin for trin.","bd.sub":"byg maskinen","bd.toMachine":"Maskine","bd.h1":"Byg viklemaskinen","bd.intro":"En drejeskive bærer sømpladen; en trådguide over kanten bevæger sig kun ind og ud og op og ned. Alt her er regnet ud fra ét sæt mål, til en sømcirkel på 600 mm med 240 søm: 3D-modellen, de printede dele, boreplanerne og styringens indstillinger. Maskinsiden planlægger bevægelserne og skriver G-koden.","bd.loading":"Indlæser 3D-modellen…","bd.pickHint":"Klik på en del for at se, hvad den er. Træk for at dreje, rul for at zoome.","bd.turn":"Drej langsomt","bd.h.numbers":"Tallene","bd.h.buy":"Dele der skal købes","bd.h.print":"Dele der skal printes","bd.printHint":"Hver fil er drejet, så den printer bedst, og ligger på printpladen. Lag på 0,2 mm, medmindre noten siger andet. FreeCAD-modellen rummer alle dele og kan ændres.","bd.fcstd":"FreeCAD-model (.FCStd)","bd.h.drill":"Boreplaner","bd.svgBase":"Plan over bunden i naturlig størrelse (SVG)","bd.svgPlatter":"Plan over drejepladen i naturlig størrelse (SVG)","bd.svgHint":"Filerne i naturlig størrelse er i millimeter: print dem i 100 % (de fleste PDF-læsere kan dele en stor side op i fliser), eller brug dem til at afmærke efter. Sømpladen bruger sømskabelonen fra appen.","bd.h.wiring":"Ledningsføring","bd.h.grbl":"Styringens indstillinger","bd.grblHint":"Send dem én gang til GRBL 1.1 fra et hvilket som helst G-kode-program; GRBL husker dem.","bd.copy":"Kopiér indstillingerne","bd.h.assembly":"Samling","bd.h.calibrate":"Opsætning og første kørsel","mc.build":"Byg den","mc.buildBtn":"Byg maskinen: dele, planer og ledninger","mc.zoomLabel":"Nærbillede af guiden og sømmet, der vikles om","mc.zoomCap":"nærbillede, naturlig størrelse","nav.machine":"Maskine","dl.machine":"Vikl det med en maskine","mc.title":"String Art — Viklemaskine","mc.meta":"Vikl et String Art-værk med en maskine: en drejende plade og en trådguide. Tjek maskinen mod værket, få et skøn over viklingstiden, se den vikle, og hent G-koden.","mc.sub":"viklemaskine","mc.back":"← Tilbage til appen","mc.h.piece":"Værket","mc.demo":"Demomønster","mc.pieceHint":"Maskinen vikler dit seneste resultat fra appen i denne browser eller en projektfil. Søm, plade og tråd kommer fra værket.","mc.h.machine":"Maskinen","mc.reset":"Anbefalede indstillinger","mc.play":"Afspil","mc.restart":"Fra starten","mc.speed":"Afspilningshastighed","mc.upright":"Hold billedet oprejst","mc.canvas":"Maskinen set forfra: pladen drejer under en fast trådguide øverst","mc.scrub":"Linje","mc.gcode":"Hent G-kode","mc.gcodeHint":"Til GRBL (eller Marlin) med tre akser. Filen starter med styringens indstillinger og opsætningstrinene; den stopper, så du kan binde tråden fast i starten og til sidst.","mc.h.checks":"Kontrol","mc.h.summary":"Vikling","mc.h.how":"Sådan vikler maskinen","mc.how1":"Pladen ligger på en drejeskive. Over dens kant sidder en trådguide, et tyndt rør, som tråden løber igennem fra en bremset spole; guiden bevæger sig kun ind og ud langs én radius og op og ned. Sådan vikles en linje til næste søm:","mc.step1":"<b>Drej.</b> Pladen drejer, til mellemrummet ved siden af næste søm er under guiden. Guiden venter lige inden for ringen, så tråden fra det sidste søm ligger hen over den åbne midte og ikke kan hænge fast.","mc.step2":"<b>Ud.</b> Guiden bevæger sig ud gennem mellemrummet, forbi sømmene.","mc.step3":"<b>Vikl.</b> Pladen drejer ét søm, så sømmet passerer guiden, og tråden kommer om bag det.","mc.step4":"<b>Ind.</b> Guiden kommer ind igen gennem mellemrummet på den anden side. Tråden er nu viklet om sømmet og strammes af spolens bremse.","mc.how2":"Hver senere vikling på samme søm lægges lidt højere, så de stables pænt. Akserne i G-koden: X er pladens drejning i grader, Y guidens afstand fra sømcirklen i mm (negativ indenfor), og Z dens højde over pladen.","about.h.math":"Matematikken bag","about.m.intro":"Her er hvert skridt, appen tager, med de ligninger, den bruger. Du skal kun kende potenser, kvadratrødder, sinus og cosinus og tegnet Σ, som betyder “læg dem alle sammen”.","about.m1.h":"1. Fra et foto til et kort over mørke","about.m1.a":"Et foto gemmer hver pixel som tre tal mellem 0 og 1 for rød, grøn og blå. Men tallene er “klemt sammen”: skærme gemmer lys efter en kurve, så de mørke nuancer får flere af tallene. Før appen regner med lys, retter den kurven ud igen og finder den virkelige mængde lys <i>L</i> ud fra den gemte værdi <i>v</i>:","about.m1.e1":"<i>L</i> = ((<i>v</i> + 0,055) / 1,055)<sup>2,4</sup>      (for meget mørke værdier: <i>L</i> = <i>v</i> / 12,92)","about.m1.b":"Vores øjne ser grøn som meget lysere end rød og blå som den mørkeste af de tre, så en pixels lysstyrke <i>Y</i> er et vægtet gennemsnit:","about.m1.e2":"<i>Y</i> = 0,2126 <i>R</i> + 0,7152 <i>G</i> + 0,0722 <i>B</i>","about.m1.c":"Tråden er sort, så appen har brug for det modsatte af lysstyrke: hvor mørkt hvert punkt skal være. Det er det ønskede mørke <i>T</i>, fra 0 (hvidt, ingen tråd) til 1 (sort, helt dækket):","about.m1.e3":"<i>T</i> = 1 − <i>Y</i>","about.m1.d":"Hvorfor rette kurven ud? Fordi tråd virker med virkeligt lys: et punkt, der er halvt dækket af sort tråd, sender halvdelen af lyset tilbage, og kun tal for virkeligt lys lægges sådan sammen.","about.m2.h":"2. Hvor sømmene sidder","about.m2.a":"Der er <i>N</i> søm med lige stor afstand på en cirkel med radius <i>R</i> omkring centrum (<i>c</i><sub>x</sub>, <i>c</i><sub>y</sub>). Søm 0 sidder øverst, og numrene går med uret. Søm <i>i</i> sidder ved vinklen","about.m2.e1":"<i>θ</i><sub><i>i</i></sub> = −90° + 360° · <i>i</i> / <i>N</i>","about.m2.b":"og placeringen findes med cosinus og sinus. På en skærm vokser <i>y</i> nedad, og det er derfor, numrene går med uret:","about.m2.e2":"<i>x</i><sub><i>i</i></sub> = <i>c</i><sub>x</sub> + <i>R</i> cos <i>θ</i><sub><i>i</i></sub>      <i>y</i><sub><i>i</i></sub> = <i>c</i><sub>y</sub> + <i>R</i> sin <i>θ</i><sub><i>i</i></sub>","about.m2.c":"En linje mellem to søm, der er <i>d</i> pladser fra hinanden, er en korde i cirklen. På en plade med diameteren <i>D</i> er den så lang:","about.m2.e3":"længde = <i>D</i> · sin(180° · <i>d</i> / <i>N</i>)","about.m2.d":"For eksempel: med 240 søm på en plade på 600 mm sidder søm 0 og 120 lige over for hinanden: sin(90°) = 1, så linjen er hele 600 mm. Søm 0 og 60 er en kvart omgang fra hinanden: 600 · sin(45°) ≈ 424 mm.","about.m3.h":"3. At tegne en linje på et gitter af pixel","about.m3.a":"En ret linje går sjældent præcis gennem midten af pixel. Appen bruger Xiaolin Wus metode: den går langs linjen én kolonne ad gangen, og hvor linjen går mellem to pixel, deler den blækket mellem dem. Hvis linjen ligger en brøkdel <i>f</i> af vejen fra midten af den øverste pixel til den nederste, får de","about.m3.e1":"<i>w</i><sub>øverst</sub> = 1 − <i>f</i>      <i>w</i><sub>nederst</sub> = <i>f</i>","about.m3.b":"så hver kolonne altid får præcis én pixel blæk. Men en skrå linje er længere end antallet af kolonner, den krydser: en linje på 45° over 100 kolonner er 141 pixel lang. Derfor får hver linje en rettelse","about.m3.e2":"<i>k</i> = længde / krydsede kolonner      (mellem 1 og √2 ≈ 1,41)","about.m4.h":"4. Hvordan tråden gør pladen mørk","about.m4.a":"Én gang tråd dækker kun en del af en pixel. I arbejdsstørrelsen er en pixel 600 mm / 700 ≈ 0,86 mm bred, og tråden er 0,25 mm tyk, så én gang tråd dækker omtrent denne brøkdel (mørkefaktoren, en indstilling, lader tråden tælle som mørkere eller lysere):","about.m4.e1":"<i>α</i> = (trådens bredde / pixlens bredde) × mørkefaktor = 0,25 / 0,86 × 1 ≈ 0,29","about.m4.b":"På en pixel i en linje med blækandelen <i>w</i> dækker én gang tråd <i>a</i> = <i>α</i> · <i>k</i> · <i>w</i> (aldrig mere end 1). Nu den vigtige idé: en ny tråd, der ligger oven på de gamle, dækker den samme brøkdel af det hvide, der <b>stadig ses</b>. Hvis <i>C</i> er, hvor mørk en pixel allerede er, er det hvide, der ses, 1 − <i>C</i>, og efter én gang mere","about.m4.e2":"1 − <i>C</i><sub>ny</sub> = (1 − <i>C</i>) · (1 − <i>a</i>)","about.m4.c":"Efter <i>n</i> gange over en hvid pixel er mørket derfor","about.m4.e3":"<i>C</i> = 1 − (1 − <i>a</i>)<sup><i>n</i></sup>","about.m4.d":"Med <i>a</i> = 0,29: én gang giver 0,29, to giver 0,50 (ikke 0,58), tre giver 0,64, ti giver 0,97. Krydsninger bliver mørkere og mørkere, men aldrig mørkere end sort — ligesom rigtig tråd.","about.m5.h":"5. At vælge den næste linje","about.m5.a":"Appen måler, hvor langt den simulerede plade <i>C</i> er fra målet <i>T</i>, med den kvadrerede fejl: for hver pixel tager den forskellen, sætter den i anden (så både for mørkt og for lyst tæller som positivt), ganger med, hvor vigtig pixlen er (<i>W</i>, fra penslen: normalt 1, op til 3 i vigtige områder), og lægger det hele sammen:","about.m5.e1":"<i>E</i> = Σ <i>W</i> · (<i>T</i> − <i>C</i>)<sup>2</sup>","about.m5.b":"At vikle én linje mere gør hver af dens pixel mørkere med <i>δ</i> = <i>a</i> · (1 − <i>C</i>). Hvor meget sænker det fejlen? Når man regner (<i>T</i> − <i>C</i>)<sup>2</sup> − (<i>T</i> − <i>C</i> − <i>δ</i>)<sup>2</sup> ud, får man den forbedring, linjen giver:","about.m5.e2":"Δ<i>E</i> = Σ<sub>linjens pixel</sub> <i>W</i> · <i>δ</i> · (2(<i>T</i> − <i>C</i>) − <i>δ</i>)","about.m5.c":"En pixel hjælper, så længe den stadig er lysere, end den skal være, med mere end halvdelen af <i>δ</i>; når den er mørk nok, tæller mere tråd dér imod linjen. Fra det søm, tråden er ved, regner appen Δ<i>E</i> ud for hver linje, den må vikle som den næste (omkring 200), vikler den med størst Δ<i>E</i> og gentager fra den anden ende af linjen.","about.m5.d":"Det kaldes en <b>grådig</b> metode: den tager altid det bedste næste skridt og kigger aldrig længere frem. Hvorfor ikke finde den allerbedste rækkefølge? Med 200 valg ved hvert af 3.000 skridt er der 200<sup>3000</sup> mulige rækkefølger — et tal med omkring 6.900 cifre. Ingen computer kunne prøve dem alle; den grådige metode skal kun bruge 200 × 3.000 = 600.000 udregninger, og det tager få sekunder.","about.m6.h":"6. Hvornår der skal stoppes, og at foretrække korte linjer","about.m6.a":"Appen stopper efter det højeste antal linjer, du tillader, eller når det bedste Δ<i>E</i> har ligget under en lille grænse <i>ε</i> (normalt 0) i 20 linjer i træk: så hjælper ingen linje længere, og de sidste 20 linjer tages ud igen. Længdestraffen <i>β</i> dividerer hver linjes point med dens længde <i>ℓ</i> opløftet til en potens:","about.m6.e1":"point = Δ<i>E</i> / <i>ℓ</i><sup><i>β</i></sup>","about.m6.b":"Med <i>β</i> = 0 ændres intet; med <i>β</i> = 1 skal en dobbelt så lang linje give dobbelt så stor forbedring for at vinde, så korte linjer nær kanten får en bedre chance.","about.m7.h":"7. At måle resultatet","about.m7.a":"Kvadratroden af den gennemsnitlige kvadrerede fejl tager gennemsnittet af de kvadrerede forskelle over alle <i>n</i> pixel i cirklen og trækker kvadratroden, så den er i samme enheder som mørket (0 er perfekt):","about.m7.e1":"RMSE = √( Σ (<i>T</i> − <i>C</i>)<sup>2</sup> / <i>n</i> )","about.m7.b":"SSIM (strukturel lighed) sammenligner små udsnit på 7 × 7 af de to billeder: deres gennemsnitlige mørke <i>μ</i>, hvor meget de varierer (<i>σ</i>), og hvor meget de varierer sammen (<i>σ</i><sub>TC</sub>). Den er 1, når udsnittene passer, og tæt på 0, når de intet har til fælles:","about.m7.e2":`SSIM = (2<i>μ</i><sub>T</sub><i>μ</i><sub>C</sub> + <i>c</i><sub>1</sub>)(2<i>σ</i><sub>TC</sub> + <i>c</i><sub>2</sub>) / ((<i>μ</i><sub>T</sub><sup>2</sup> + <i>μ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>1</sub>)(<i>σ</i><sub>T</sub><sup>2</sup> + <i>σ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>2</sub>))
<i>c</i><sub>1</sub> = 0,0001, <i>c</i><sub>2</sub> = 0,0009`,"about.m7.c":"De små tal <i>c</i><sub>1</sub> og <i>c</i><sub>2</sub> forhindrer, at der divideres med nul i ensfarvede udsnit. Tæt på er tråd et virvar af tynde linjer, så appen giver også SSIM, efter at begge billeder er gjort lidt slørede — det ligner mere det, du ser fra et par skridts afstand. Til sidst er den tråd, du skal bruge, summen af alle linjelængderne fra trin 2 plus 10 % til omviklingen om sømmene og slæk.","about.m8.h":"8. At justere billedet","about.m8.a":"Kontrast og lysstyrke virker på den gemte værdi <i>v</i>: kontrasten <i>s</i> strækker den væk fra mellemgrå, lysstyrken <i>b</i> flytter den, og gammaen <i>γ</i> bøjer den, så mellemtonerne bliver mørkere, når <i>γ</i> er over 1:","about.m8.e1":"<i>v</i>′ = ((<i>v</i> − 0,5) · <i>s</i> + 0,5 + <i>b</i>)<sup><i>γ</i></sup>","about.m8.b":"Den lokale kontrastforstærkning (CLAHE) deler billedet op i et gitter på 8 × 8 felter. I hvert felt tæller den, hvor mange pixel der har hver nuance (et histogram), og giver hver nuance en ny værdi: den andel af feltets pixel, der er mørkere end den. Nuancer, som mange pixel deler, bliver spredt ud, så der kommer detaljer frem i flade områder. Først begrænses hver optælling til en grænse, så støj ikke pustes op, og nabofelter blandes, så der ikke ses sømme.","tm.help":"Mellemrum, Enter eller → for det næste søm; ← for at gå tilbage; Esc for at lukke. Din plads gemmes efter hvert trin, så du kan lukke og fortsætte senere.","tm.nextBtn":"Næste ▶","tm.go":"Gå","tm.goto":"Gå til linje","tm.back":"◀ Tilbage","tm.board":"Pladen med linjerne, der er viklet indtil nu, og den næste linje fremhævet","tm.after":"Efter","tm.before":"Før","tm.next":"Næste søm","tm.close":"Luk","tm.full":"Fuld skærm","tm.speak":"Sig sømmet højt","tm.title":"Viklevisning","h.presets":"Forvalg","dl.thread":"Viklevisning","in.project":"Åbn et projekt","in.projNote":"Et projekt gemmer billedet, som beregningen så det, ikke det originale foto. Upload fotoet igen for at ændre beskæringen, justeringerne eller penselstrøgene.","h.template":"Sømskabelon","tpl.hint":"Sømmenes placering i fuld størrelse, nummereret, til at tape på pladen. Udskriv i faktisk størrelse (100 %, ikke “tilpas til side”), og kontrollér kvadratet på 100 mm med en lineal.","tpl.paper":"Papir","tpl.pages":"Sider til udskrift","tpl.svg":"Ét ark (SVG)","dl.png":"Forhåndsvisning (PNG)","dl.project":"Projektfil","dl.instructions":"Hent viklevejledningen","dl.csv":"Rækkefølge (CSV)","brush.hint":"Mal på visningen Mål. Varme områder tæller op til tre gange så meget og får flere linjer; kolde områder tæller ned til en femtedel. Brug den til øjne, en mund eller en kant, der betyder noget.","brush.clear":"Fjern penselstrøgene","brush.size":"Penselstørrelse","brush.down":"Mindre vigtigt","brush.up":"Vigtigere","brush.off":"Fra","h.brush":"Vigtighedspensel","h.seen":"Som beregningen ser det","adj.reset":"Nulstil justeringerne","adj.clip":"Klipgrænse (højere forstærker mere)","adj.clahe":"Lokal kontrastforstærkning (CLAHE)","adj.gamma":"Gamma (over 1 gør mellemtonerne mørkere)","adj.contrast":"Kontrast","adj.brightness":"Lysstyrke","h.adjust":"Justér","crop.reset":"Nulstil beskæringen","crop.rotate":"Drej","crop.zoom":"Zoom","crop.hint":"Træk for at flytte billedet; rul eller knib for at zoome.","crop.label":"Billedet under pladens cirkel: træk for at flytte det, rul eller knib for at zoome",title:"String Art — Én tråd, ét billede",meta:"Gør et billede til trådkunst: én sammenhængende tråd viklet mellem søm på en rund ramme. Appen finder den rækkefølge af søm, der bedst gengiver billedet, og viser en realistisk forhåndsvisning — alt sammen i din browser.",sub:"én tråd, ét billede","nav.about":"Om","nav.projects":"← Alle projekter","h.picture":"Billede","in.upload":"Upload et billede","in.sample":"Brug eksemplet","in.thumb":"Billedet, som beregningen ser det","in.hint":"Vælg et billede: et ansigt eller en genstand med stærk kontrast mod en ensfarvet baggrund virker bedst. Intet bliver uploadet; alt kører i din browser.","h.params":"Parametre","run.run":"Beregn","run.pause":"Pause","run.cancel":"Annullér","view.label":"Vis","view.thread":"Tråd","view.target":"Mål","view.both":"Side om side","view.threadLabel":"Forhåndsvisning af tråden på pladen","view.threadCap":"tråd, tegnet i sin rigtige tykkelse","view.targetLabel":"Målet, beregningen sigter efter","view.targetCap":"ønsket mørke","h.metrics":"Resultat","log.summary":"Beregningslog","about.title":"Om String Art","about.back":"← Tilbage til appen","about.h1":"Om String Art","about.p1":"String Art gør et billede til en vejledning til et klassisk stykke håndværk: søm rundt om en rund plade og én sort tråd, viklet fra søm til søm tusindvis af gange, indtil trådens krydsninger tegner billedet. Appen regner rækkefølgen af søm ud og viser, hvordan det færdige værk kommer til at se ud.","about.h.how":"Sådan vælger den linjerne","about.how":"Billedet bliver til et kort over, hvor mørkt hvert punkt skal være. Fra ét søm prøver appen hver linje, den må vikle som den næste, og beholder den, der bringer den simulerede plade tættest på kortet; derefter fortsætter den fra linjens ende. Tråden gør pladen mørk, som rigtig tråd gør: hver gang dækker den en del af det hvide, der stadig ses, så krydsninger bliver mørkere, men aldrig mørkere end sort. Den stopper, når den når det højeste antal linjer, du tillader, eller når ingen linje gør billedet bedre længere.","about.h.numbers":"Tallene","about.numbers":"RMSE måler, hvor langt den simulerede plade er fra målet, pixel for pixel (0 er et perfekt match). SSIM sammenligner lokal lysstyrke, kontrast og struktur (1 er ens); fordi tråd er en fin tekstur af linjer, giver appen også SSIM efter en let sløring, tættere på det, du ser fra et par skridts afstand. Trådlængden er summen af alle linjerne plus 10 % til omvikling om sømmene og slæk.","about.h.private":"Dine billeder bliver hos dig","about.private":"Alt kører i din browser. Billeder bliver aldrig uploadet.","about.h.status":"Hvad den gør","about.status":"Version 1.0. Forbered billedet — beskær, zoom og drej det, justér lysstyrke, kontrast og gamma, forstærk den lokale kontrast, og mal det, der betyder noget — med et tjek, der advarer om billeder, som ikke vil fungere godt; vælg et forvalg eller indstil hver parameter; og se tråden blive viklet på. Udskriv derefter sømskabelonen i fuld størrelse og viklevejledningen, og vikl værket med viklevisningen, der viser (og kan sige) det næste søm og husker, hvor du er. Dine indstillinger og dit seneste resultat huskes i denne browser."}},m="sa-lang",d={en:{name:"English",html:"en",locale:"en-US",label:"Language"},es:{name:"Español",html:"es-419",locale:"en-US",label:"Idioma"},da:{name:"Dansk",html:"da",locale:"da-DK",label:"Sprog"}},p={en:null,es:h,da:c},u=e=>e==="en"||e==="es"||e==="da";function g(){if(typeof location>"u")return"en";let e=null;try{e=new URLSearchParams(location.search).get("lang")}catch{e=null}if(u(e)){try{localStorage.setItem(m,e)}catch{}return e}try{const r=localStorage.getItem(m);if(u(r))return r}catch{}const a=typeof navigator<"u"&&(navigator.languages?.[0]||navigator.language)||"";return/^es\b/i.test(a)?"es":/^da\b/i.test(a)?"da":"en"}const i=g(),l=p[i],b=d[i].locale,v=(e,a)=>a?e.replace(/\{(\w+)\}/g,(r,o)=>a[o]!=null?String(a[o]):r):e;function k(e,a){const r=l?.T[e];return v(r??e,a)}function w(e,a){const r=e.toFixed(a);return i==="da"?r.replace(".",","):r}function y(e){return Math.round(e).toLocaleString(b)}function f(e){return i==="en"?e:e.replace(/^([^#?]*)(\?[^#]*)?/,(a,r,o)=>{const t=new URLSearchParams((o||"").slice(1));return t.set("lang",i),r+"?"+t.toString()})}function j(e=document){if(document.documentElement.lang=d[i].html,l){e.querySelectorAll("[data-i18n]").forEach(r=>{const o=l.H[r.dataset.i18n];o!=null&&(r.innerHTML=o)}),e.querySelectorAll("[data-i18n-attr]").forEach(r=>{r.dataset.i18nAttr.split(",").forEach(o=>{const[t,n]=o.split("="),s=l.H[n];s!=null&&r.setAttribute(t,s)})});const a=document.querySelector("title[data-i18n]");a&&l.H[a.dataset.i18n]&&(document.title=l.H[a.dataset.i18n])}e.querySelectorAll("a[href]").forEach(a=>{const r=a.getAttribute("href");/^(index|about|machine|build|calculations)\.html/.test(r)&&a.setAttribute("href",f(r))})}function T(){const e=document.getElementById("langSel");e&&(e.innerHTML=Object.keys(d).map(a=>`<option value="${a}" lang="${d[a].html}">${d[a].name}</option>`).join(""),e.value=i,e.setAttribute("aria-label",d[i].label),e.addEventListener("change",()=>{const a=e.value;if(a===i)return;try{localStorage.setItem(m,a)}catch{}const r=new URLSearchParams(location.search);r.set("lang",a),location.href=location.pathname+"?"+r.toString()+location.hash}))}const S="1.6.0";export{d as L,k as T,S as V,j as a,b,w as f,y as i,i as l,T as m};
